    #[test]
    fn the_palette_remembers_what_was_launched() {
        // Demandé le 07/11/2026 : le champ vide montre les dernières commandes lancées,
        // la plus récente en haut ; ↑ / ↓ et Entrée les relancent ; gardées sur disque.
        use crate::palette::Item;
        use tri::sort::SortKey;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let palette = |h: &mut Harness<'_, TriApp>| {
            press(h, Key::P, CMD | Modifiers::SHIFT);
        };
        let shown = |h: &Harness<'_, TriApp>| -> Vec<Item> {
            h.state()
                .palette
                .as_ref()
                .map(|p| p.hits.iter().map(|hit| hit.item.clone()).collect())
                .unwrap_or_default()
        };
        palette(&mut h);
        assert!(shown(&h).is_empty(), "rien encore");
        for query in ["trier par etoiles", "trier par nom"] {
            type_text(&mut h, query);
            press(&mut h, Key::Enter, Modifiers::NONE);
            assert!(h.state().palette.is_none());
            palette(&mut h);
        }
        assert_eq!(
            shown(&h),
            [
                Item::Action(Action::SortBy(SortKey::Name)),
                Item::Action(Action::SortBy(SortKey::Stars))
            ]
        );
        assert!(h.query_by_label(&t!("palette-recent")).is_some());
        // ↓ puis Entrée : la précédente.
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().order.key, SortKey::Stars);
        // Relancée : de nouveau en tête ; écrit dans le dossier de données.
        let data = h.state().data_dir.clone().unwrap();
        assert_eq!(
            crate::palette::load_history(&data),
            [
                Item::Action(Action::SortBy(SortKey::Stars)),
                Item::Action(Action::SortBy(SortKey::Name))
            ]
        );
        // Taper cherche ; effacer revient à l'historique.
        palette(&mut h);
        type_text(&mut h, "zoom");
        assert_ne!(shown(&h)[0], Item::Action(Action::SortBy(SortKey::Stars)));
        for _ in 0..4 {
            press(&mut h, Key::Backspace, Modifiers::NONE);
        }
        assert_eq!(shown(&h)[0], Item::Action(Action::SortBy(SortKey::Stars)));
    }

    #[test]
    fn the_palette_shows_and_changes_the_controls_of_the_panel() {
        // Proposition du 07/11/2026 (idée de l'utilisateur) : sous une action, le même
        // contrôle que dans le panneau, son état, changeable sans quitter la palette.
        let (mut h, _dir) = harness();
        allow_stacks(&mut h);
        h.run_steps(3);
        h.state_mut().metadata_panel = false;
        press(&mut h, Key::P, CMD | Modifiers::SHIFT);
        type_text(&mut h, "empiler");
        let stacks = t!("panel-grid-stacks-on");
        assert_eq!(h.query_all_by_label(&stacks).count(), 1, "une fois");
        let before = h.state().stacking;
        h.get_by_label(&stacks).click();
        h.run_steps(3);
        assert_ne!(h.state().stacking, before, "basculé");
        assert!(h.state().palette.is_some(), "la palette reste ouverte");
        // Plusieurs actions pour le même contrôle (l'ordre) : une seule liste.
        for _ in 0.."empiler".len() {
            press(&mut h, Key::Backspace, Modifiers::NONE);
        }
        type_text(&mut h, "trier par");
        let hits = h.state().palette.as_ref().map_or(0, |p| p.hits.len());
        assert!(hits > 1, "{hits}");
        let reverse = h.state().action_tip(Action::SortReverse);
        assert_eq!(h.query_all_by_label(&reverse).count(), 1);
        // Une action sans contrôle : rien dessous.
        assert_eq!(h.state().palette_control(Action::NavNext), None);
        assert_eq!(
            h.state()
                .palette_control(Action::SortBy(tri::sort::SortKey::Stars)),
            Some(Control::Sort)
        );
    }

