        // F1 passe à la liste complète.
        press(&mut h, Key::Questionmark, Modifiers::SHIFT);
        press(&mut h, Key::F1, Modifiers::NONE);
        assert!(h.state().help_here.is_none());
        assert!(h.state().help);
        press(&mut h, Key::Escape, Modifiers::NONE);
