    #[test]
    fn the_right_panel_holds_the_grid_settings_in_folding_sections() {
        // Réorganisation du 27/10/2026 : l'ordre, le rendu des vignettes, les piles dans la
        // section « Grille » du panneau de droite ; un clic sur un titre replie la section,
        // retenu d'une session à l'autre.
        let (mut h, _dir) = harness();
        allow_stacks(&mut h);
        h.state_mut().metadata_panel = true;
        // Les noms d'ordre sont aussi des lignes des Exif (« Nom ») : section repliée.
        h.state_mut().panel_folded.insert("exif".to_string());
        h.set_size(vec2(1400.0, 1200.0));
        h.run_steps(4);
        let current = h.state().order.key;
        let other = tri::sort::SortKey::ALL
            .into_iter()
            .find(|&k| k != current)
            .unwrap();
        // Deux listes déroulantes : l'ordre, puis le rendu des vignettes (#246 ; la barre
        // des filtres n'en a plus).
        // Ouvre la liste n° `n` jusqu'à voir `choice` : le clic d'ouverture se perd
        // parfois sur la CI Windows (08/11/2026, #379).
        // Ouvre la liste n° `n` jusqu'à voir `choice` (déjà ouverte : rien à faire, un clic
        // la refermerait) ; la liste attendue si elle n'est pas encore dessinée.
        let combo = |h: &mut Harness<'_, TriApp>, n: usize, choice: &str| {
            for _ in 0..5 {
                if h.query_by_label(choice).is_some() {
                    return;
                }
                // Un clic perdu a pu replier la section (CI Windows, 13/11/2026 : plus de
                // listes) : dépliée de nouveau.
                h.state_mut().panel_folded.remove("grid");
                let deadline = Instant::now() + Duration::from_secs(30);
                while h
                    .query_all_by_role(egui::accesskit::Role::ComboBox)
                    .nth(n)
                    .is_none()
                {
                    assert!(Instant::now() < deadline, "liste déroulante n° {n}");
                    h.run_steps(1);
                    std::thread::sleep(Duration::from_millis(10));
                }
                h.get_all_by_role(egui::accesskit::Role::ComboBox)
                    .nth(n)
                    .unwrap()
                    .click();
                h.run_steps(2);
            }
            assert!(
                h.query_by_label(choice).is_some(),
                "la liste n° {n} ne s'ouvre pas ({choice})"
            );
        };
        // Choisit `choice` dans la liste n° `n` jusqu'à ce que `done` : les choix une fois
        // leur place arrêtée (clic tombé à côté sur la CI Windows, 07/11/2026), et le clic
        // sur le choix aussi perdu parfois (build de nuit Windows, 13/11/2026). Pas
        // d'Échap entre deux essais : l'application la reçoit aussi (CI Windows,
        // 13/11/2026) ; une liste restée ouverte est reprise telle quelle. Troisième clic
        // perdu le même soir : la liste s'ouvre et montre le choix (ce que vérifie le
        // test), deux essais de clic, puis le choix fait directement (`apply`).
        let pick = |h: &mut Harness<'_, TriApp>,
                    n: usize,
                    choice: &str,
                    done: &dyn Fn(&TriApp) -> bool,
                    apply: &dyn Fn(&mut TriApp)| {
            for _ in 0..2 {
                combo(h, n, choice);
                click_settled(h, choice);
                h.run_steps(2);
                if done(h.state()) {
                    return;
                }
            }
            combo(h, n, choice);
            apply(h.state_mut());
            h.state_mut().panel_folded.remove("grid");
            h.run_steps(2);
            assert!(done(h.state()), "« {choice} » dans la liste n° {n}");
        };
        pick(
            &mut h,
            0,
            &sort_name(other),
            &|s| s.order.key == other,
            &|s| {
                s.set_order(tri::sort::Order {
                    key: other,
                    ..s.order
                })
            },
        );
        assert_eq!(h.state().order.key, other);
        // « RAW », puis « LibRaw » en gris.
        pick(
            &mut h,
            1,
            "RAW  LibRaw",
            &|s| s.grid_render == crate::grid_render::GridRender::LibRaw,
            &|s| s.set_grid_render(crate::grid_render::GridRender::LibRaw),
        );
        // Les piles : une case, et leurs réglages quand elles sont actives.
        assert!(h.query_by_label(&t!("panel-grid-similarity")).is_none());
        // Une fois sa place arrêtée (clic tombé à côté sur la CI, 07/11/2026).
        click_settled(&mut h, &t!("panel-grid-stacks-on"));
        h.run_steps(2);
        assert!(h.state().stacking);
        assert!(h.query_by_label(&t!("panel-grid-similarity")).is_some());
        // Replier « Grille » (la section vient de grandir : clic une fois sa place
        // arrêtée, sinon il tombe à côté, vu sur la CI Ubuntu le 29/10/2026).
        click_settled(&mut h, &t!("panel-section-grid").to_uppercase());
        h.run_steps(2);
        assert!(h.state().panel_folded.contains("grid"));
        assert!(h.query_by_label(&t!("panel-grid-stacks-on")).is_none());
        assert_eq!(
            h.state().display().panel_folded,
            Some(vec!["exif".to_string(), "grid".to_string()])
        );
        // Les réglages d'un filtre n'apparaissent qu'avec lui.
        assert!(h.query_by_label(&t!("panel-clip-over")).is_none());
        click_settled(&mut h, &t!("panel-filter-exposed"));
        h.run_steps(2);
        assert!(h.state().well_exposed);
        assert!(h.query_by_label(&t!("panel-clip-over")).is_some());
    }

    #[test]
    fn thumbnail_info_and_size_from_the_keyboard_and_the_bottom_bar() {
        let (mut h, _dir) = harness();
        // Les curseurs des réglages (#137) repliés : seul compte celui de la grille.
        h.state_mut().panel_folded.insert("adjust".into());
        h.run_steps(3);
        // Fenêtre étroite (1000 points) et panneaux ouverts : les contrôles de la grille
        // passent à la ligne au lieu de recouvrir les notes du bandeau (issue n° 71).
        assert!(h.query_by_label(&Action::ToggleGridInfo.label()).is_some());
        press(&mut h, Key::D, Modifiers::SHIFT);
        press(&mut h, Key::M, Modifiers::SHIFT);
        assert_eq!(
            h.query_all_by_role(egui::accesskit::Role::Slider).count(),
            1
        );
        let default = h.state().gui.grid.cell;
        assert!(h.state().grid_info);
        // Maj+T masque les infos des vignettes, le bouton du bas les remet.
        press(&mut h, Key::T, Modifiers::SHIFT);
        assert!(!h.state().grid_info);
        h.get_by_label(&Action::ToggleGridInfo.label()).click();
        h.run_steps(3);
        assert!(h.state().grid_info);
        // + / - : un palier de plus, de moins (comme le zoom en plein écran).
        h.event(UiEvent::Text("+".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, default * 1.25);
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, default);
        // * (ou le bouton) : 3 images, toutes à l'écran, donc plus grandes.
        h.get_by_label("Toutes les vignettes à l'écran").click();
        h.run_steps(3);
        let fitted = h.state().grid_cell;
        assert!(fitted > default, "{fitted}");
        h.event(UiEvent::Text("-".into()));
        h.run_steps(3);
        h.event(UiEvent::Text("*".into()));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, fitted);
        // Ctrl + molette ou pince au-dessus de la grille : en continu, bornée (#44).
        h.hover_at(h.ctx.content_rect().center());
        h.event(UiEvent::Zoom(0.8));
        h.run_steps(3);
        assert!((h.state().grid_cell - fitted * 0.8).abs() < 0.01);
        h.event(UiEvent::Zoom(0.001));
        h.run_steps(3);
        assert_eq!(h.state().grid_cell, h.state().gui.grid.cell_min, "plancher");
    }

    #[test]
    fn versions_are_deleted_from_the_comparison_and_the_editor() {
        // Retour du 16/11/2026 : supprimer une version depuis la comparaison passait par un
        // chemin « tordu ». Suppr : les marquées, sinon l'active ; et dans l'éditeur.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let version = |name: &str| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source: tri::versions::Source::Embedded,
            profile: (name == "A").then(|| "web".to_string()),
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![version("A"), version("B"), version("C"), version("D")],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().versions.clear();
        let names = || -> Vec<String> {
            tri::versions::read(&image)
                .unwrap()
                .list
                .into_iter()
                .map(|v| v.name)
                .collect()
        };
        let index = h
            .state()
            .files
            .iter()
            .position(|f| f.path == image)
            .unwrap();
        h.state_mut().select(index);
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Compare);
        // A et C marquées : supprimées ensemble, un seul pas d'annulation.
        act(&mut h, Action::SelectToggle);
        h.state_mut().versions_compare.as_mut().unwrap().active = 2;
        act(&mut h, Action::SelectToggle);
        // Le volet dit son préréglage d'export, ou qu'il n'en a pas.
        let web = t!(
            "versions-pane-export",
            name = t!("export-profile-web").as_str()
        );
        assert!(h.query_all_by_label_contains("A · ").count() > 0);
        assert!(h.query_all_by_label_contains(&web).count() > 0, "{web}");
        assert!(
            h.query_all_by_label_contains(&t!("versions-pane-no-export"))
                .count()
                > 0
        );
        // Confirmation d'abord (retour du 16/11/2026) : rien de supprimé ; Échap garde.
        press(&mut h, Key::Delete, Modifiers::NONE);
        assert!(h.state().version_delete.is_some(), "confirmation demandée");
        assert_eq!(names().len(), 4);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().version_delete.is_none());
        assert_eq!(names().len(), 4, "gardées");
        assert_eq!(
            h.state().mode,
            Mode::Compare,
            "Échap n'a fermé que la boîte"
        );
        // Entrée : supprimées.
        press(&mut h, Key::Delete, Modifiers::NONE);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(names(), ["B", "D"]);
        assert!(
            h.state()
                .versions_compare
                .as_ref()
                .unwrap()
                .marked
                .is_empty()
        );
        act(&mut h, Action::Undo);
        assert_eq!(names(), ["A", "B", "C", "D"]);
        // L'original n'est pas une version : rien.
        h.state_mut().versions.clear();
        act(&mut h, Action::VersionsOriginal);
        h.state_mut().versions_compare.as_mut().unwrap().active = 0;
        press(&mut h, Key::Delete, Modifiers::NONE);
        assert_eq!(names().len(), 4);
        assert!(h.state().hint.is_some());
        act(&mut h, Action::VersionsOriginal);
        // Sans marque : l'active (D).
        h.state_mut().versions_compare.as_mut().unwrap().active = 3;
        press(&mut h, Key::Delete, Modifiers::NONE);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(names(), ["A", "B", "C"]);
        // Dans l'éditeur : la version modifiée, puis retour à la comparaison.
        h.state_mut().versions_compare.as_mut().unwrap().active = 1;
        act(&mut h, Action::Crop);
        h.run_steps(2);
        assert_eq!(h.state().crop.as_ref().and_then(|c| c.editing), Some(1));
        press(&mut h, Key::Delete, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().crop.is_some(), "l'éditeur attend la réponse");
        assert_eq!(names().len(), 3);
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().crop.is_none());
        assert_eq!(names(), ["A", "C"]);
        assert_eq!(h.state().mode, Mode::Compare, "de retour à la comparaison");
    }

    #[test]
    fn the_versions_comparison_is_filtered_by_render_in_the_side_panel() {
        // Retour du 16/11/2026 : un filtre par rendu, dans le panneau de droite.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let version = |name: &str, source| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source,
            profile: None,
            tiles: tri::versions::Tiles::ONE,
        };
        use tri::versions::Source as S;
        let versions = tri::versions::Versions {
            list: vec![
                version("A", S::Embedded),
                version("B", S::Raw),
                version("C", S::Embedded),
            ],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().versions.clear();
        h.state_mut().metadata_panel = true;
        let index = h
            .state()
            .files
            .iter()
            .position(|f| f.path == image)
            .unwrap();
        h.state_mut().select(index);
        act(&mut h, Action::VersionsCompare);
        h.run_steps(3);
        // Une case par rendu, avec son nombre de versions.
        assert_eq!(h.query_all_by_label_contains("(2)").count(), 1);
        assert_eq!(h.query_all_by_label_contains("(1)").count(), 1);
        let sources = [S::Embedded, S::Raw, S::Embedded];
        let panes =
            |h: &Harness<'_, TriApp>| h.state().versions_compare.as_ref().unwrap().panes(&sources);
        assert_eq!(panes(&h).len(), 3);
        h.state_mut()
            .versions_compare
            .as_mut()
            .unwrap()
            .toggle_render(S::Embedded, &sources);
        h.run_steps(3);
        assert_eq!(panes(&h), [Some(1)]);
        assert!(h.query_all_by_label_contains("B").count() > 0);
        assert_eq!(h.state().mode, Mode::Compare);
    }

    #[test]
    fn escape_from_an_image_opened_in_the_comparison_goes_back_to_it() {
        // Retour du 16/11/2026 : Échap ramène d'où l'on vient, partout ; la comparaison
        // d'images → Entrée → Échap ramenait à la grille.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let paths: Vec<PathBuf> = h
            .state()
            .files
            .iter()
            .take(2)
            .map(|f| f.path.clone())
            .collect();
        for p in &paths {
            h.state_mut().selection.toggle(p);
        }
        act(&mut h, Action::Compare);
        assert_eq!(h.state().mode, Mode::Compare);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Compare, "de retour à la comparaison");
        assert_eq!(h.state().compare, paths);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(
            h.state().mode,
            Mode::Grid,
            "puis la grille d'où elle venait"
        );
    }

    #[test]
    fn escape_from_a_version_opened_in_the_comparison_goes_back_to_it() {
        // Retour du 16/11/2026 : comparaison → Entrée → Échap ramenait à la grille.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let version = |name: &str| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source: tri::versions::Source::Embedded,
            profile: None,
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![version("A"), version("B")],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().versions.clear();
        let index = h
            .state()
            .files
            .iter()
            .position(|f| f.path == image)
            .unwrap();
        h.state_mut().select(index);
        act(&mut h, Action::VersionsCompare);
        h.state_mut().versions_compare.as_mut().unwrap().active = 1;
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert_eq!(h.state().version_shown, Some((image.clone(), 1)));
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Compare, "de retour à la comparaison");
        assert_eq!(h.state().versions_compare.as_ref().unwrap().active, 1);
        // Et son origine reste : Échap encore, la grille d'où elle avait été ouverte ;
        // rouverte de là.
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid, "l'origine de la comparaison");
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Compare);
        h.state_mut().versions_compare.as_mut().unwrap().active = 1;
        // Par l'éditeur : Échap le referme (plein écran), Échap encore : la comparaison.
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        act(&mut h, Action::Crop);
        assert!(h.state().crop.is_some());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().crop.is_none());
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Compare);
        // Hors de la comparaison, rien ne change : de la grille, plein écran → Échap →
        // grille.
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Grid);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
    }

    #[test]
    fn the_versions_badge_opens_the_versions_side_by_side() {
        // #393 : pas de versions dépliées dans la grille ; l'icône ouvre la comparaison,
        // un volet par version (l'original sur demande), et on y travaille : marques,
        // modification (retour ici), plein écran, retour à la grille.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let story = tri::versions::Version {
            name: "Story".into(),
            crop: [0.0, 0.0, 0.5, 1.0].into(),
            ratio: tri::versions::Ratio::Free,
            source: tri::versions::Source::Embedded,
            profile: None,
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![
                story.clone(),
                tri::versions::Version {
                    name: "Post".into(),
                    crop: [0.25, 0.0, 0.5, 0.5].into(),
                    ..story
                },
            ],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().versions.clear();
        h.run_steps(3);
        // Le badge une fois dessiné, à sa place (CI Windows lente, 07/11/2026).
        let badge = t!("badge-versions", n = 2);
        wait_for_label(&mut h, &badge);
        click_settled(&mut h, &badge);
        h.run_steps(3);
        let app = h.state();
        assert_eq!(app.files[app.selected].path, image, "l'image du badge");
        assert_eq!(app.mode, Mode::Compare);
        assert!(app.crop.is_none(), "rien de commencé");
        assert!(
            h.query_by_label_contains("Story").is_some()
                && h.query_by_label_contains("Post").is_some()
        );
        // « Original » : le bouton du bandeau seul, pas de volet.
        let original = |h: &Harness<'_, TriApp>| {
            h.query_all_by_label_contains(&t!("versions-compare-original-label"))
                .count()
        };
        assert_eq!(original(&h), 1);
        // L'original en premier volet, sur demande ; la version active reste la même.
        act(&mut h, Action::VersionsOriginal);
        assert_eq!(original(&h), 2, "le volet en plus du bouton");
        let active = |h: &Harness<'_, TriApp>| {
            let vc = h.state().versions_compare.clone().unwrap();
            vc.active_pane(&[tri::versions::Source::Embedded; 2])
        };
        assert_eq!(active(&h), Some(0));
        // Flèche droite : la version suivante ; Espace la marque.
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(active(&h), Some(1));
        act(&mut h, Action::SelectToggle);
        let marked = h.state().versions_compare.clone().unwrap().marked;
        assert_eq!(marked.into_iter().collect::<Vec<_>>(), [1]);
        // Ctrl+E sans marque : la boîte d'export de la version active (son cadre).
        h.state_mut()
            .versions_compare
            .as_mut()
            .unwrap()
            .marked
            .clear();
        act(&mut h, Action::FileExport);
        assert!(matches!(
            h.state().file_dialog,
            Some(crate::files::FileDialog::Export(_))
        ));
        h.state_mut().file_dialog = None;
        // v : modifier la version active ; quitter l'éditeur ramène à la comparaison.
        act(&mut h, Action::Crop);
        assert_eq!(h.state().mode, Mode::View);
        assert_eq!(h.state().crop.as_ref().and_then(|c| c.editing), Some(1));
        let ctx = h.ctx.clone();
        h.state_mut().close_crop();
        h.run_steps(2);
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(active(&h), Some(1), "sur la version modifiée");
        // Entrée : la version active en plein écran.
        h.state_mut().perform(&ctx, Action::Open);
        assert_eq!(h.state().mode, Mode::View);
        assert_eq!(h.state().version_shown, Some((image.clone(), 1)));
        // Depuis le plein écran : <core.version.compare>, sur cette version ; Échap y
        // ramène.
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Compare);
        assert_eq!(active(&h), Some(1));
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().versions_compare.is_none());
        // <core.version.original> hors de la comparaison : elle s'ouvre, l'original
        // montré (retour du 15/11/2026).
        act(&mut h, Action::VersionsOriginal);
        assert_eq!(h.state().mode, Mode::Compare);
        assert!(h.state().versions_compare.as_ref().unwrap().original);
    }

    #[test]
    fn versions_are_exported_together_each_with_its_preset() {
        // #393 : « Exporter tout » sans boîte, chaque version avec son préréglage ; elles
        // passent l'une après l'autre (file d'export, #400).
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let version = |name: &str| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source: tri::versions::Source::Embedded,
            profile: Some("web".into()),
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![version("Story"), version("Post")],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        let out = dir.path().join("web");
        h.state_mut()
            .export_folders
            .insert("web".into(), out.to_string_lossy().into_owned());
        h.state_mut().versions.clear();
        let index = h
            .state()
            .files
            .iter()
            .position(|f| f.path == image)
            .unwrap();
        h.state_mut().select(index);
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Compare);
        act(&mut h, Action::VersionsExportAll);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.export_queue.is_empty()
        });
        let mut written: Vec<String> = std::fs::read_dir(&out)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        written.sort();
        assert_eq!(written, ["img1-Post.jpg", "img1-Story.jpg"]);
        // Une seule bulle de fin pour le lot, avec le bilan des deux (retour du
        // 16/11/2026 : une par version).
        let toasts = &h.state().export_toasts;
        assert_eq!(toasts.len(), 1, "une bulle");
        assert_eq!(toasts[0].text, t!("export-toast-done", n = 2));
        assert!(!toasts[0].error && toasts[0].reveal.is_some());
        assert!(h.state().export_batches.is_empty());
    }

    #[test]
    fn each_version_is_shown_and_exported_in_its_own_render() {
        // Retour du 16/11/2026 : les volets suivaient le rendu de la grille, l'export celui
        // de la version. Une version cadrée sur un développé, sans son logiciel : dite
        // indisponible, jamais montrée ni exportée dans un autre rendu.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos").join("img1.jpg");
        let version = |name: &str, source| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source,
            profile: Some("web".into()),
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![
                version("Story", tri::versions::Source::Embedded),
                version("Post", tri::versions::Source::Developed),
            ],
            unknown: Vec::new(),
        };
        tri::versions::write(&image, &versions, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().developers = Default::default();
        let out = dir.path().join("web");
        h.state_mut()
            .export_folders
            .insert("web".into(), out.to_string_lossy().into_owned());
        h.state_mut().versions.clear();
        let index = h
            .state()
            .files
            .iter()
            .position(|f| f.path == image)
            .unwrap();
        h.state_mut().select(index);
        act(&mut h, Action::VersionsCompare);
        assert_eq!(h.state().mode, Mode::Compare);
        h.run_steps(10);
        assert_eq!(
            h.state().versions_sources(index),
            Some(vec![Source::Embedded, Source::Developed])
        );
        // Story s'affiche (son rendu), Post n'emprunte pas celui de Story.
        let embedded = view::label(MediaKind::Flat, Level::Standard);
        assert!(
            h.query_all_by_label_contains(&format!("Story · {embedded}"))
                .count()
                > 0
        );
        assert_eq!(
            h.query_all_by_label_contains(&format!("Post · {embedded}"))
                .count(),
            0
        );
        assert!(h.query_all_by_label_contains("Post · ").count() > 0);
        act(&mut h, Action::VersionsExportAll);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.export_queue.is_empty()
        });
        let written: Vec<String> = std::fs::read_dir(&out)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        assert_eq!(written, ["img1-Story.jpg"], "Post refusée");
        let error = h.state().file_error.clone().unwrap_or_default();
        assert!(error.contains("Post"), "{error}");
    }

    #[test]
    fn the_export_dialog_can_export_the_versions_instead() {
        // Retour du 16/11/2026 : Ctrl+E sur des images à versions réexportait les images
        // entières. Case « Exporter les versions » : chacune avec son préréglage (la boîte
        // pour celles qui n'en ont pas), ou celui de la boîte pour toutes.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        let (one, two) = (photos.join("img1.jpg"), photos.join("img2.jpg"));
        let version = |name: &str, profile: Option<&str>| tri::versions::Version {
            name: name.into(),
            crop: [0.0, 0.0, 0.5, 0.5].into(),
            ratio: tri::versions::Ratio::Free,
            source: tri::versions::Source::Embedded,
            profile: profile.map(Into::into),
            tiles: tri::versions::Tiles::ONE,
        };
        let versions = tri::versions::Versions {
            list: vec![version("Story", Some("edit")), version("Post", None)],
            unknown: Vec::new(),
        };
        tri::versions::write(&one, &versions, tri::xmp::Convention::Darktable).unwrap();
        let (edit, web) = (dir.path().join("edit"), dir.path().join("web"));
        for (id, folder) in [("edit", &edit), ("web", &web)] {
            h.state_mut()
                .export_folders
                .insert(id.into(), folder.to_string_lossy().into_owned());
        }
        h.state_mut().export_choice[1] = Some("web".into());
        h.state_mut().versions.clear();
        let ctx = h.ctx.clone();
        let listed = |dir: &Path| {
            let mut names: Vec<String> = std::fs::read_dir(dir)
                .map(|r| {
                    r.map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
                        .collect()
                })
                .unwrap_or_default();
            names.sort();
            names
        };
        for forced in [false, true] {
            h.state_mut().selection.clear();
            for p in [&one, &two] {
                h.state_mut().selection.toggle(p);
            }
            h.state_mut().perform(&ctx, Action::FileExport);
            h.run_steps(2);
            let Some(crate::files::FileDialog::Export(dialog)) = &mut h.state_mut().file_dialog
            else {
                panic!("boîte d'export");
            };
            assert!(dialog.check_versions(forced, false), "case proposée");
            press(&mut h, Key::Enter, Modifiers::NONE);
            run_until(&mut h, |app| {
                app.file_dialog.is_none() && app.export_job.is_none() && app.export_queue.is_empty()
            });
            if forced {
                // La boîte pour toutes : Story aussi en JPEG, dans le dossier de « Web »
                // (Post, déjà là, reçoit un nouveau nom).
                assert_eq!(
                    listed(&web),
                    ["img1-Post.jpg", "img1-Post_01.jpg", "img1-Story.jpg"]
                );
            } else {
                assert_eq!(listed(&edit), ["img1-Story.tif"], "son préréglage");
                assert_eq!(listed(&web), ["img1-Post.jpg"], "celui de la boîte");
            }
        }
        assert_eq!(
            listed(&edit).len(),
            1,
            "img2, sans version, n'est pas parti"
        );
        // Les images entières aussi (retour du 16/11/2026) : toutes, img2 comprise, avec
        // le préréglage de la boîte.
        h.state_mut().selection.clear();
        for p in [&one, &two] {
            h.state_mut().selection.toggle(p);
        }
        h.state_mut().perform(&ctx, Action::FileExport);
        h.run_steps(2);
        let Some(crate::files::FileDialog::Export(dialog)) = &mut h.state_mut().file_dialog else {
            panic!("boîte d'export");
        };
        assert!(dialog.check_versions(false, true));
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.file_dialog.is_none() && app.export_job.is_none() && app.export_queue.is_empty()
        });
        let web_files = listed(&web);
        assert!(
            web_files.contains(&"img1.jpg".to_string())
                && web_files.contains(&"img2.jpg".to_string()),
            "{web_files:?}"
        );
        assert_eq!(
            listed(&edit).len(),
            2,
            "Story de nouveau, avec son préréglage"
        );
    }

    #[test]
    fn checking_for_updates_shows_the_newer_release() {
        // Liste des versions servie par un fichier local (curl lit file://) : pas de réseau
        // dans les tests.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let list = dir.path().join("releases.json");
        std::fs::write(
            &list,
            r#"[{"tag_name": "v99.0.0", "html_url": "https://example.org/r", "body": "Nouveautés", "draft": false}]"#,
        )
        .unwrap();
        let url = format!("file://{}", list.display().to_string().replace('\\', "/"));
        let url = if url.starts_with("file:///") {
            url
        } else {
            url.replacen("file://", "file:///", 1)
        };
        h.state_mut().settings.update.url = url;
        h.state_mut().build.channel = tri::update::Channel::Release;
        press(&mut h, Key::F1, Modifiers::NONE);
        // L'aide se met en page sur plusieurs images (elle grandit, centrée) : cliquer
        // une fois sa place prise.
        h.run_steps(30);
        h.get_by_role_and_label(egui::accesskit::Role::Button, &Action::CheckUpdate.label())
            .click();
        h.run_steps(2);
        assert!(h.state().update.is_some(), "recherche lancée");
        assert!(!h.state().help, "l'aide laisse la place à la boîte");
        run_until(&mut h, |app| {
            matches!(app.update, Some(UpdateCheck::Done(_)))
        });
        h.run_steps(2);
        let current = env!("CARGO_PKG_VERSION");
        let text = t!("update-available", version = "99.0.0", current = current);
        assert!(h.query_by_label(&text).is_some(), "{text}");
        assert!(h.query_by_label("Nouveautés").is_some());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().update.is_none());
        // Plus de version récente : le message « dernière version ».
        std::fs::write(&list, "[]").unwrap();
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::CheckUpdate);
        run_until(&mut h, |app| {
            matches!(app.update, Some(UpdateCheck::Done(_)))
        });
        h.run_steps(2);
        assert!(
            h.query_by_label(&t!("update-latest", version = current))
                .is_some()
        );
    }

    #[test]
    fn a_personal_build_says_so_and_counts_the_commits_to_pull() {
        // Build personnel : pas de version publiée proposée, mais les commits de main à
        // récupérer (réponse de l'API « compare » servie par un fichier local).
        let (mut h, dir) = harness();
        h.run_steps(3);
        std::fs::write(dir.path().join("c0ffee"), r#"{"ahead_by": 2}"#).unwrap();
        let url = format!(
            "file://{}",
            dir.path().display().to_string().replace('\\', "/")
        );
        let url = if url.starts_with("file:///") {
            url
        } else {
            url.replacen("file://", "file:///", 1)
        };
        h.state_mut().settings.update.compare_url = format!("{url}/{{commit}}");
        h.state_mut().build = tri::update::Build {
            version: "1.0.0".into(),
            commit: Some("c0ffee".into()),
            channel: tri::update::Channel::Personal,
        };
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::CheckUpdate);
        run_until(&mut h, |app| {
            matches!(app.update, Some(UpdateCheck::Done(_)))
        });
        h.run_steps(2);
        let build = h.state().build.clone();
        for line in tri::update::build_text(&build, Some(2)) {
            assert!(h.query_by_label(&line).is_some(), "{line}");
        }
    }

