    #[test]
    fn a_darktable_clone_has_its_own_thumbnail_and_its_own_notes() {
        // Une vignette par clone (choix du 29/10/2026) : `img0_01.jpg.xmp` sans
        // `img0_01.jpg` est le clone n° 1 de `img0.jpg`, noté dans son propre sidecar.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        std::fs::write(
            photos.join("img0_01.jpg.xmp"),
            r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1" xmp:Rating="2"/></rdf:RDF></x:xmpmeta>"#,
        )
        .unwrap();
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        // Rendu « Couverture » (31/10/2026) : la pile se replie sur le développement
        // préféré, sinon le plus récent (en JPEG boîtier, sur la photo).
        h.state_mut()
            .set_grid_render(crate::grid_render::GridRender::Cover);
        // Son chemin propre (`tri::developments`), jamais sur le disque.
        let clone = photos.join("img0@dt-01.jpg");
        run_until(&mut h, |app| {
            app.loading.is_none()
                && app.files.len() == 4
                && app.status.iter().all(|s| s.thumbnail == Avail::Ready)
        });
        let i = h
            .state()
            .files
            .iter()
            .position(|f| f.path == clone)
            .expect("le clone dans la liste, juste après son original");
        assert_eq!(h.state().files[i - 1].path, photos.join("img0.jpg"));
        assert_eq!(h.state().folder.notes.notes(&clone).stars, 2);
        // Barre d'état : les photos, le développement compté à part (31/10/2026).
        h.get_by_label_contains("3 images (0 RAW, 1 dév.)");
        // Pile de développements repliée (30/10/2026) : la grille montre la photo (sa
        // couverture, sans préféré : le clone, le plus récent) et « 1 dév. » ; Maj+W passe
        // au développement suivant, sur place.
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3, "une vignette par photo");
        assert!(
            h.state().stacks.folded_count(i).is_some(),
            "le clone est la couverture"
        );
        assert_eq!(selected_name(&h), "img0@dt-01.jpg");
        act(&mut h, Action::DevNext);
        assert_eq!(h.state().selected, i - 1, "en boucle : la photo");
        let keys = h.state().keymap.keys_for(Action::DevToggle).join(" / ");
        let has = if keys.is_empty() { "no" } else { "yes" };
        let badge = t!("dev-count-tip", n = 1, keys = keys.clone(), has = has);
        assert!(!badge.contains("· :") && !badge.contains("()"), "{badge}");
        h.get_by_label(&badge);
        act(&mut h, Action::DevPrev);
        assert_eq!(h.state().selected, i);
        // `s` déplie (comme une pile, 31/10/2026) : les deux vignettes, cadrées.
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 4);
        assert!(h.state().stacks.in_unfolded_developments(i));
        assert!(h.query_by_label(&badge).is_none());
        type_text(&mut h, ")");
        type_text(&mut h, ")");
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3);
        assert_eq!(h.state().selected, i, "la sélection reste sur le clone");
        // Pastille « replier » sur chaque vignette dépliée (31/10/2026) : clic = replier.
        let fold_tip = t!("dev-fold-tip", keys = keys, has = has);
        assert!(
            h.query_by_label(&fold_tip).is_none(),
            "repliée : pas de pastille"
        );
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        h.run_steps(2);
        assert_eq!(
            h.query_all_by_label(&fold_tip).count(),
            2,
            "une par vignette"
        );
        h.get_all_by_label(&fold_tip).next().unwrap().click();
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3, "repliée au clic");
        assert!(h.state().dev_preferred.is_empty());
        // Alt+clic : replier en gardant ce développement (le clone) comme couverture.
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        h.run_steps(2);
        h.get_all_by_label(&fold_tip)
            .nth(1)
            .unwrap()
            .click_modifiers(Modifiers::ALT);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3, "repliée");
        assert!(
            h.state().dev_preferred.contains(&clone),
            "le clone en couverture"
        );
        assert_eq!(h.state().selected, i);
        // Maj+Entrée sans bascule : sur le clone, il reste la couverture ; sur la photo,
        // la photo elle-même (14/11/2026 : JPEG et LibRaw peuvent être la couverture), une
        // seule.
        press(&mut h, Key::Enter, Modifiers::SHIFT);
        assert!(h.state().dev_preferred.contains(&clone), "pas une bascule");
        act(&mut h, Action::DevNext);
        assert_eq!(h.state().selected, i - 1, "la photo");
        press(&mut h, Key::Enter, Modifiers::SHIFT);
        let photo = h.state().files[i - 1].path.clone();
        assert!(
            h.state().dev_preferred.contains(&photo) && h.state().dev_preferred.len() == 1,
            "la photo, seule couverture : {:?}",
            h.state().dev_preferred
        );
        // Maj+S replie toutes les piles, développements compris (31/10/2026), puis les
        // redéplie toutes.
        type_text(&mut h, "(");
        type_text(&mut h, "(");
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 4);
        press(&mut h, Key::S, Modifiers::SHIFT);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3, "tout replié");
        press(&mut h, Key::S, Modifiers::SHIFT);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 4, "tout déplié");
        press(&mut h, Key::S, Modifiers::SHIFT);
        h.run_steps(2);
        assert_eq!(h.state().stacks.shown.len(), 3);
        act(&mut h, Action::DevPrev);
        assert_eq!(h.state().selected, i, "retour sur le clone");
        press(&mut h, Key::Num4, Modifiers::SHIFT);
        assert_eq!(
            tri::xmp::read_sidecar(&photos.join("img0_01.jpg.xmp"))
                .unwrap()
                .stars,
            4
        );
        assert_eq!(
            h.state().folder.notes.notes(&photos.join("img0.jpg")).stars,
            0,
            "l'original garde ses notes"
        );
    }

    #[test]
    fn the_grid_render_decides_the_cover_of_a_photo() {
        // Décidé le 31/10/2026 : JPEG boîtier et LibRaw, la photo ; « Couverture », le
        // préféré sinon le plus récent ; un logiciel, son développement principal.
        use crate::grid_render::GridRender;
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        let darktable = r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#"><rdf:Description rdf:about="" xmlns:darktable="http://darktable.sf.net/" darktable:xmp_version="5" darktable:history_end="1"/></rdf:RDF></x:xmpmeta>"#;
        std::fs::write(photos.join("img0_01.jpg.xmp"), darktable).unwrap();
        std::fs::write(photos.join("img0.jpg.xmp"), darktable).unwrap();
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 5);
        h.run_steps(2);
        let (photo, main, clone) = (
            photos.join("img0.jpg"),
            photos.join("img0@dt.jpg"),
            photos.join("img0@dt-01.jpg"),
        );
        let cover = |h: &mut Harness<'_, TriApp>| {
            h.run_steps(2);
            let app = h.state();
            let i = app.files.iter().position(|f| f.path == photo).unwrap();
            let range = app.stacks.developments_of(i).unwrap().clone();
            let c = range
                .clone()
                .find(|&i| app.stacks.folded_count(i).is_some())
                .expect("une pile repliée");
            file_name(&app.files[c].path)
        };
        assert_eq!(h.state().grid_render, GridRender::Embedded);
        assert_eq!(cover(&mut h), "img0.jpg", "JPEG boîtier : la photo");
        h.state_mut().set_grid_render(GridRender::LibRaw);
        assert_eq!(cover(&mut h), "img0.jpg", "LibRaw : la photo");
        h.state_mut()
            .set_grid_render(GridRender::Engine(tri::develop::Engine::Darktable));
        assert_eq!(cover(&mut h), "img0@dt.jpg", "darktable : son principal");
        h.state_mut().set_grid_render(GridRender::Cover);
        h.state_mut().dev_preferred.insert(clone.clone());
        h.state_mut().stacks_dirty = true;
        assert_eq!(cover(&mut h), "img0@dt-01.jpg", "Couverture : le préféré");
        h.state_mut().dev_preferred.clear();
        h.state_mut().stacks_dirty = true;
        let latest = cover(&mut h);
        assert!(
            latest == "img0@dt.jpg" || latest == "img0@dt-01.jpg",
            "sans préféré : le plus récent, {latest}"
        );
        assert!(main != clone);
    }

    #[test]
    fn deleting_a_development_strips_its_xmp_and_ctrl_delete_takes_the_photo() {
        // Double suppression (30/10/2026) : Suppr / `x` retire le développement affiché
        // (principal darktable : son XMP sans l'historique, notes gardées) ; Ctrl+Suppr
        // supprime la photo avec tout.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        let xmp = photos.join("img0.jpg.xmp");
        std::fs::write(
            &xmp,
            concat!(
                r#"<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">"#,
                r#"<rdf:Description rdf:about="" xmlns:xmp="http://ns.adobe.com/xap/1.0/" xmlns:darktable="http://darktable.sf.net/" "#,
                r#"xmp:Rating="3" darktable:xmp_version="5" darktable:history_end="1"><darktable:history><rdf:Seq><rdf:li darktable:operation="exposure"/></rdf:Seq></darktable:history>"#,
                r#"</rdf:Description></rdf:RDF></x:xmpmeta>"#
            ),
        )
        .unwrap();
        // Les développements des seuls logiciels actifs (07/11/2026).
        h.state_mut().developers = fake_darktable();
        h.state_mut().reload_folder(None);
        // Rendu « Couverture » (31/10/2026) : la pile se replie sur le développement.
        h.state_mut()
            .set_grid_render(crate::grid_render::GridRender::Cover);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 4);
        h.run_steps(2);
        assert_eq!(
            selected_name(&h),
            "img0@dt.jpg",
            "la couverture : le développement"
        );
        press(&mut h, Key::Delete, Modifiers::NONE);
        assert!(h.state().file_dialog.is_some());
        h.get_by_label(&t!("delete-stripped", name = "img0.jpg.xmp"));
        assert!(
            h.query_by_label("img0.jpg").is_none(),
            "la photo ne part pas"
        );
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| app.file_dialog.is_none());
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 3);
        assert!(photos.join("img0.jpg").exists() && xmp.exists());
        assert!(!tri::developments::file_is_darktable(&xmp));
        assert_eq!(
            tri::xmp::read_sidecar(&xmp).unwrap().stars,
            3,
            "notes gardées"
        );
        assert_eq!(h.state().history.entries().len(), 1);
        // Annulé : le développement revient.
        press(&mut h, Key::Z, CMD);
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 4);
        assert!(tri::developments::file_is_darktable(&xmp));
        h.run_steps(2);
        assert_eq!(selected_name(&h), "img0@dt.jpg");
        // Ctrl+Suppr depuis le développement : la photo et son XMP.
        press(&mut h, Key::Delete, CMD);
        assert!(h.state().file_dialog.is_some());
        h.get_by_label("img0.jpg");
        h.get_by_label("img0.jpg.xmp");
        assert!(
            h.query_by_label(&t!("delete-stripped", name = "img0.jpg.xmp"))
                .is_none()
        );
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| app.file_dialog.is_none());
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 2);
        assert!(!photos.join("img0.jpg").exists() && !xmp.exists());
        assert!(h.state().file_error.is_none());
    }

    #[test]
    fn undo_and_redo_ratings_and_refuse_after_an_outside_change() {
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = dir.path().join("photos/img0.jpg");
        press(&mut h, Key::Num3, Modifiers::SHIFT);
        press(&mut h, Key::X, Modifiers::SHIFT);
        assert_eq!(h.state().history.entries().len(), 2, "un pas par note");
        // u : la dernière note (rejet) défaite, puis Ctrl+Z : les étoiles.
        press(&mut h, Key::Z, CMD);
        assert_eq!(tri::xmp::read(&image).unwrap().flag, Flag::None);
        assert_eq!(tri::xmp::read(&image).unwrap().stars, 3);
        assert!(h.state().notice.as_ref().unwrap().0.starts_with("Annulé"));
        press(&mut h, Key::Z, CMD);
        assert_eq!(tri::xmp::read(&image).unwrap().stars, 0);
        assert_eq!(
            h.state().folder.notes.notes(&image).stars,
            0,
            "affichage relu"
        );
        // Rétablir : Ctrl+R puis Ctrl+Maj+Z.
        press(&mut h, Key::Y, CMD);
        press(&mut h, Key::Z, CMD | Modifiers::SHIFT);
        let notes = tri::xmp::read(&image).unwrap();
        assert_eq!((notes.stars, notes.flag), (3, Flag::Rejected));
        // Modifié ailleurs : refus, rien ne bouge.
        let mut changed = notes.clone();
        changed.stars = 5;
        tri::xmp::write_sidecar(&dir.path().join("photos/img0.jpg.xmp"), &changed).unwrap();
        press(&mut h, Key::Z, CMD);
        assert_eq!(tri::xmp::read(&image).unwrap().stars, 5);
        assert!(
            h.state()
                .file_error
                .as_ref()
                .unwrap()
                .contains("modifiées ailleurs"),
            "{:?}",
            h.state().file_error
        );
        assert_eq!(h.state().history.position(), 2);
    }

    #[test]
    fn undo_a_rename_and_a_move_and_walk_the_history_list() {
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        // Renommer img0 en quai.
        press(&mut h, Key::F2, Modifiers::NONE);
        h.event(UiEvent::Text("quai".into()));
        h.run_steps(2);
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(photos.join("quai.jpg").exists());
        // Déplacer l'image courante vers un dossier (Ctrl+X, couper).
        let dest = dir.path().join("dest");
        std::fs::create_dir(&dest).unwrap();
        press(&mut h, Key::X, CMD);
        h.event(UiEvent::Text(dest.display().to_string()));
        h.run_steps(2);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| app.file_dialog.is_none());
        assert_eq!(h.state().history.entries().len(), 2);
        let moved = std::fs::read_dir(&dest).unwrap().count();
        assert_eq!(moved, 1);
        // Ctrl+H : la liste ; « État au lancement » défait tout.
        press(&mut h, Key::H, Modifiers::CTRL);
        assert!(h.state().history_open);
        wait_for_label(&mut h, "État au lancement");
        h.get_by_label("État au lancement").click();
        h.run_steps(3);
        assert_eq!(h.state().history.position(), 0);
        assert!(photos.join("img0.jpg").exists() && !photos.join("quai.jpg").exists());
        assert_eq!(std::fs::read_dir(&dest).unwrap().count(), 0, "revenue");
        assert_eq!(h.state().files.len(), 3, "dossier relu");
        // Le pas le plus récent : tout refait.
        let label = h.state().history.entries()[1].label.clone();
        wait_for_label(&mut h, &label);
        h.get_by_label(&label).click();
        h.run_steps(3);
        assert_eq!(h.state().history.position(), 2);
        assert!(photos.join("quai.jpg").exists() || dest.join("quai.jpg").exists());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().history_open);
    }

