    #[test]
    fn clearing_the_filters_goes_back_to_the_start_of_the_grid_at_once() {
        // Retour du 18/11/2026 : la grille gardait en haut la première image visible sous
        // le filtre (au milieu de la liste complète), puis se recalait en plusieurs fois.
        let names: Vec<String> = (0..120).map(|i| format!("img{i:03}.jpg")).collect();
        let refs: Vec<&str> = names.iter().map(String::as_str).collect();
        let (mut h, _dir) = harness_files(&refs, 32, 24);
        run_until(&mut h, |app| app.files.len() == 120);
        h.state_mut().name_query = "img1".into();
        h.state_mut().apply_filter();
        h.run_steps(3);
        assert!(h.state().files.len() < 120);
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::NavLast);
        h.run_steps(3);
        let filtered_offset = h.state().scroll_offset;
        assert!(filtered_offset > 0.0, "scrolled down under the filter");
        h.state_mut().perform(&ctx, Action::FilterClear);
        assert_eq!(h.state().files.len(), 120);
        assert_eq!(h.state().selected, 0, "the first image");
        h.run_steps(1);
        assert_eq!(
            h.state().scroll_offset,
            0.0,
            "at once (was {filtered_offset})"
        );
        h.run_steps(5);
        assert_eq!(h.state().scroll_offset, 0.0, "and it stays there");
    }

    #[test]
    fn the_image_one_was_on_stays_at_the_top_while_the_grid_settles() {
        // Retour du 19/11/2026 : dossier rouvert sur l'image où l'on en était (#414), sans
        // cache ; les piles se formant, la grille défilait d'elle-même et s'arrêtait sur
        // des vignettes grises.
        let names: Vec<String> = (0..120).map(|i| format!("img{i:03}.jpg")).collect();
        let refs: Vec<&str> = names.iter().map(String::as_str).collect();
        let (mut h, _dir) = harness_files(&refs, 32, 24);
        run_until(&mut h, |app| app.files.len() == 120);
        h.run_steps(3);
        let held = 80;
        let top = |h: &Harness<'_, TriApp>| {
            let app = h.state();
            (held / app.layout.columns) as f32 * app.layout.row_pitch()
        };
        h.state_mut().selected = held;
        h.state_mut().hold_selection = true;
        h.state_mut().reveal = Some(Reveal::Top);
        h.run_steps(2);
        assert_eq!(h.state().scroll_offset, top(&h));
        // Piles regroupées, liste refiltrée : la région affichée ne l'emporte pas.
        h.state_mut().stacks_dirty = true;
        h.state_mut().refilter(Reveal::Minimal);
        h.state_mut().reveal = Some(Reveal::Start);
        h.run_steps(2);
        assert_eq!(h.state().selected, held);
        assert_eq!(h.state().scroll_offset, top(&h), "still at the top");
        // Une action rend la main.
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::NavFirst);
        assert!(!h.state().hold_selection);
        h.run_steps(2);
        assert_eq!(h.state().scroll_offset, 0.0);
    }

    #[test]
    fn a_rating_shows_at_once_and_is_written_in_the_background() {
        // 19/11/2026 (`TRI_IO_WATCH`, iCloud) : noter figeait la fenêtre le temps d'une
        // dizaine d'accès disque. La note s'affiche tout de suite et s'écrit en fond ; un
        // échec remet ce qui est sur le disque, et le dit.
        let (mut h, dir) = harness();
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 3);
        h.state_mut().notes_inline = false;
        let ctx = h.ctx.clone();
        let path = h.state().files[0].path.clone();
        h.state_mut().perform(&ctx, Action::Stars(3));
        assert_eq!(
            h.state().folder.notes.notes(&path).stars,
            3,
            "tout de suite"
        );
        run_until(&mut h, |app| {
            app.note_writes.as_ref().is_some_and(|w| w.waiting() == 0)
        });
        let sidecar = tri::xmp::sidecar_path(&path, tri::xmp::Convention::Darktable);
        assert_eq!(
            tri::xmp::read(&path).unwrap().stars,
            3,
            "{}",
            sidecar.display()
        );
        assert!(h.state().note_error.is_none());
        // Dossier en lecture seule : l'écriture échoue, la note revient à 3.
        let photos = dir.path().join("photos");
        let mut perms = std::fs::metadata(&photos).unwrap().permissions();
        perms.set_readonly(true);
        std::fs::set_permissions(&photos, perms.clone()).unwrap();
        std::fs::set_permissions(&sidecar, perms).unwrap();
        h.state_mut().perform(&ctx, Action::Stars(5));
        assert_eq!(h.state().folder.notes.notes(&path).stars, 5);
        run_until(&mut h, |app| {
            app.note_writes.as_ref().is_some_and(|w| w.waiting() == 0)
        });
        let back = h.state().folder.notes.notes(&path).stars;
        let error = h.state().note_error.clone();
        // Rendre les droits avant de vérifier (le dossier temporaire doit s'effacer).
        let mut perms = std::fs::metadata(&photos).unwrap().permissions();
        #[allow(clippy::permissions_set_readonly_false)]
        perms.set_readonly(false);
        std::fs::set_permissions(&photos, perms.clone()).unwrap();
        std::fs::set_permissions(&sidecar, perms).unwrap();
        assert_eq!(back, 3, "ce qui est sur le disque");
        assert!(error.is_some(), "l'échec est dit");
    }

