    #[test]
    fn under_wayland_the_window_size_is_still_remembered() {
        // Retour du 25/10/2026 (#58) : sous Wayland, ni position ni `inner_rect` (egui
        // ne les connaît pas) ; la taille de la zone de dessin est retenue quand même.
        let (mut h, _dir) = harness();
        h.state_mut().gui.window_save_ms = 0;
        let viewport = h
            .input_mut()
            .viewports
            .entry(egui::ViewportId::ROOT)
            .or_default();
        viewport.inner_rect = None;
        viewport.outer_rect = None;
        h.run_steps(3);
        let kept = h.state().window_kept.expect("retenue");
        let size = h.ctx.content_rect().size();
        assert_eq!(kept.size, [size.x, size.y]);
        assert_eq!(
            kept.position, None,
            "position inconnue : le compositeur la choisit"
        );
    }

    #[test]
    fn a_maximized_window_is_maximized_again_after_the_first_frame() {
        // Retour du 26/10/2026 (#58) : sous Wayland, la fenêtre agrandie ne l'était plus
        // au lancement suivant ; l'agrandissement est redemandé, une fois.
        let (mut h, _dir) = harness();
        h.state_mut().maximize_pending = true;
        let maximize = |h: &Harness<'_, TriApp>| {
            h.output()
                .viewport_output
                .values()
                .any(|v| v.commands.contains(&egui::ViewportCommand::Maximized(true)))
        };
        h.step();
        assert!(maximize(&h), "redemandé");
        assert!(!h.state().maximize_pending);
        h.step();
        assert!(!maximize(&h), "une seule fois");
    }

    #[test]
    fn the_window_is_remembered_once_still() {
        // Issue n° 58 : la fenêtre (ici celle du banc de test) est retenue une fois
        // immobile depuis `window_save_ms`, et écrite avec l'état d'affichage.
        let (mut h, dir) = harness();
        h.state_mut().gui.window_save_ms = 60_000;
        // Le banc de test ne donne pas la fenêtre : celle d'une vraie, déplacée.
        let viewport = h
            .input_mut()
            .viewports
            .entry(egui::ViewportId::ROOT)
            .or_default();
        viewport.inner_rect = Some(Rect::from_min_size(pos2(50.0, 80.0), vec2(1000.0, 700.0)));
        viewport.outer_rect = Some(Rect::from_min_size(pos2(50.0, 50.0), vec2(1000.0, 730.0)));
        h.run_steps(3);
        assert!(h.state().window_now.is_some(), "suivie");
        assert_eq!(
            h.state().window_kept,
            None,
            "pas encore immobile assez longtemps"
        );
        h.state_mut().gui.window_save_ms = 0;
        h.run_steps(2);
        let kept = h.state().window_kept.expect("retenue");
        assert_eq!(kept.size, [1000.0, 700.0]);
        assert_eq!(kept.position, Some([50.0, 50.0]), "coin du cadre");
        assert!(!kept.maximized);
        let saved = crate::state::load(&dir.path().join("data"));
        assert_eq!(saved.window, Some(kept), "écrite dans l'état d'affichage");
    }

    #[test]
    fn an_unmounted_card_shows_in_devices_and_a_click_mounts_it() {
        // #113 : support branché mais pas monté (Linux) : grisé sous « Périphériques »,
        // un clic le monte (ici un périphérique qui n'existe pas : le refus s'affiche).
        let (mut h, _dir) = harness();
        h.state_mut().folder_panel = true;
        let card = tri::places::Place {
            name: "X-T4".into(),
            path: PathBuf::from("/dev/tri-test-absent"),
            kind: tri::places::PlaceKind::Device,
        };
        let ctx = h.ctx.clone();
        h.state_mut().set_volumes(&ctx, vec![card]);
        h.run_steps(2);
        assert!(
            h.query_by_label(&t!("folders-section-devices").to_uppercase())
                .is_some()
        );
        h.get_by_label("X-T4").click();
        h.run_steps(2);
        assert!(
            h.state().offload.is_none(),
            "rien à décharger avant le montage"
        );
        let start = Instant::now();
        while h.state().mounting.is_some() && start.elapsed() < Duration::from_secs(20) {
            std::thread::sleep(Duration::from_millis(20));
            h.run_steps(1);
        }
        let (text, error) = h.state().notice.clone().expect("message");
        assert!(error, "{text}");
        assert!(text.contains("X-T4"), "{text}");
    }

