    #[test]
    fn the_search_sliders_move_from_the_keyboard() {
        // Retour du 22/11/2026 : les curseurs des recherches (couleur, palettes proches,
        // semblables) ne se réglaient pas au clavier : → les pousse d'un pas, Entrée les
        // remet à leur valeur par défaut.
        use crate::actions::Scope;
        let (mut h, _dir) = harness();
        h.set_size(vec2(1400.0, 1200.0));
        h.run_steps(3);
        choose_palette(&mut h, Some(tri::palette::SourceKind::Camera));
        h.state_mut().set_palette_colour(Some([0.6, 0.1, 0.05]));
        h.run_steps(2);
        press(&mut h, Key::B, Modifiers::CTRL);
        press(&mut h, Key::L, Modifiers::NONE);
        assert_eq!(h.state().focus, Scope::Metadata);
        let radius =
            |h: &Harness<'static, TriApp>| h.state().palette_colour.as_ref().unwrap().radius;
        let start = radius(&h);
        // Ligne par ligne jusqu'au curseur de la couleur : → le pousse.
        let mut moved = false;
        for _ in 0..60 {
            press(&mut h, Key::ArrowDown, Modifiers::NONE);
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            h.run_steps(1);
            if radius(&h) != start {
                moved = true;
                break;
            }
        }
        assert!(moved, "→ sur le curseur de la couleur");
        let max = h.state().settings.palette.colour_radius_max;
        let step = h.state().gui.metadata.slider_step * max / 2.0;
        assert!((radius(&h) - (start + step)).abs() < 1e-5);
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(1);
        assert_eq!(
            radius(&h),
            h.state().settings.palette.colour_radius,
            "Entrée : défaut"
        );
    }

    #[test]
    fn the_right_panel_settings_work_from_the_keyboard() {
        // Retour du 27/10/2026 : ↑ / ↓ parcourent aussi les réglages, Tab / Maj+Tab
        // passent d'une section à l'autre, Espace actionne, ← / → font varier.
        use crate::actions::Scope;
        let (mut h, _dir) = harness();
        h.state_mut().metadata_panel = true;
        h.set_size(vec2(1400.0, 1200.0));
        h.run_steps(3);
        press(&mut h, Key::B, Modifiers::CTRL);
        press(&mut h, Key::L, Modifiers::NONE);
        assert_eq!(h.state().focus, Scope::Metadata);
        h.run_steps(2);
        let titles: Vec<usize> = (0..h.state().side_items.len())
            .filter(|&i| h.state().side_items[i])
            .collect();
        assert!(titles.len() >= 3, "{titles:?}");
        // Filtres, grille, EXIF, réglages (#137), palette (#492) : les filtres sont le 5e
        // titre en partant de la fin.
        let filters = titles[titles.len() - 5];
        while h.state().side_cursor != Some(filters) {
            press(&mut h, Key::Tab, Modifiers::NONE);
        }
        // En tête des filtres, RAW et JPEG (retour du 28/10/2026) : Espace décoche RAW,
        // puis le recoche.
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        press(&mut h, Key::Space, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(h.state().filter, KindFilter::FlatOnly, "RAW décoché");
        press(&mut h, Key::Space, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(h.state().filter, KindFilter::All, "RAW recoché");
        // Puis le premier filtre (« nettes ») : Espace l'allume, son curseur apparaît
        // dessous.
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        let before = h.state().blur_rule.is_some();
        press(&mut h, Key::Space, Modifiers::NONE);
        h.run_steps(2);
        assert_ne!(h.state().blur_rule.is_some(), before, "Espace coche");
        assert_eq!(
            h.state().focus,
            Scope::Metadata,
            "le clavier reste au panneau"
        );
        if h.state().blur_rule.is_some() {
            press(&mut h, Key::ArrowDown, Modifiers::NONE);
            let t = h.state().blur_strictness;
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            h.run_steps(2);
            let step = h.state().gui.metadata.slider_step;
            assert!((h.state().blur_strictness - (t + step)).abs() < 1e-6);
        }
        // Maj+Tab : le titre de la section ; ← la replie, → la déplie.
        press(&mut h, Key::Tab, Modifiers::SHIFT);
        assert_eq!(h.state().side_cursor, Some(filters));
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().panel_folded.contains("filters"));
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        h.run_steps(2);
        assert!(!h.state().panel_folded.contains("filters"));
    }

    #[test]
    fn a_filter_change_shows_the_image_count_for_a_moment() {
        // Idée de l'utilisateur, 27/10/2026 : « JPEG » seul dans un dossier de RAW ne
        // laissait rien, sans qu'on le remarque.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        assert!(h.state().filter_toast_at.is_none(), "pas à l'ouverture");
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::FilterCycle);
        h.run_steps(2);
        assert!(h.state().filter_toast_at.is_some());
        // La recherche par nom n'en fait pas (son champ montre déjà le nombre).
        h.state_mut().filter_toast_at = None;
        h.state_mut().name_query = "x".into();
        h.state_mut().apply_filter();
        h.run_steps(2);
        assert!(h.state().filter_toast_at.is_none());
        // Un curseur de sévérité d'un filtre actif aussi (#304).
        h.state_mut().name_query.clear();
        h.state_mut().well_exposed = true;
        h.state_mut().apply_filter();
        h.run_steps(2);
        h.state_mut().filter_toast_at = None;
        h.state_mut().clip_strictness.0 = 0.5;
        h.run_steps(2);
        assert!(
            h.state().filter_toast_at.is_some(),
            "curseur « brûlé » bougé"
        );
        // Elle s'en va d'elle-même.
        h.state_mut().gui.grid.filter_toast_ms = 0;
        h.state_mut().perform(&ctx, Action::FilterCycle);
        h.run_steps(2);
        assert!(h.state().filter_toast_at.is_none());
    }

    #[test]
    fn folder_sections_fold_and_stay_folded() {
        // Retour du 27/10/2026 : repliables comme celles du panneau de droite, retenues
        // d'une session à l'autre.
        let (mut h, dir) = harness();
        h.state_mut().folder_panel = true;
        let place = |name: &str, kind| tri::places::Place {
            name: name.into(),
            path: dir.path().to_path_buf(),
            kind,
        };
        h.state_mut().tree = Tree::with_places(
            vec![
                place("Perso", tri::places::PlaceKind::Home),
                place("Racine", tri::places::PlaceKind::Root),
            ],
            false,
        );
        h.run_steps(2);
        // Tab : d'une section à l'autre.
        h.state_mut().tree.set_cursor(0);
        h.state_mut().focus = crate::actions::Scope::Folders;
        press(&mut h, Key::Tab, Modifiers::NONE);
        assert_eq!(h.state().tree.cursor(), Some(1), "section Système");
        press(&mut h, Key::Tab, Modifiers::SHIFT);
        assert_eq!(h.state().tree.cursor(), Some(0));
        h.state_mut().focus = crate::actions::Scope::Images;
        let title = t!("folders-section-personal").to_uppercase();
        h.get_by_label(&title).click();
        h.run_steps(2);
        assert!(h.query_by_label("Perso").is_none(), "lignes repliées");
        assert!(h.query_by_label(&title).is_some(), "titre gardé");
        let saved = h.state().display().panel_folded.unwrap();
        assert_eq!(saved, ["folders-personal"]);
        // Au lancement suivant : toujours repliée.
        h.state_mut().save_display();
        h.state_mut()
            .tree
            .set_folded(tri::places::Section::Personal, false);
        h.state_mut().restore_display();
        assert!(h.state().tree.is_folded(tri::places::Section::Personal));
    }

    #[test]
    fn computations_resume_when_the_drive_comes_back() {
        // Issue n° 98 : disque du dossier ouvert retiré sans éjection pendant les calculs,
        // puis rebranché : le dossier est relu, les calculs repartent.
        let (mut h, dir) = harness();
        let drive = tri::places::Place {
            name: "usb".into(),
            path: dir.path().to_path_buf(),
            kind: tri::places::PlaceKind::Volume,
        };
        let ctx = h.ctx.clone();
        h.state_mut().set_volumes(&ctx, vec![drive.clone()]);
        h.run_steps(2);
        let generation = h.state().engine.as_ref().unwrap().generation;
        h.state_mut().set_volumes(&ctx, vec![]);
        h.state_mut().set_volumes(&ctx, vec![drive]);
        assert!(
            h.state().engine.as_ref().unwrap().generation > generation,
            "travail relancé"
        );
        assert_eq!(h.state().notice.as_ref().unwrap().0, t!("volume-back"));
        assert_eq!(h.state().files.len(), 3);
    }

    #[test]
    fn an_image_argument_opens_its_folder_on_it() {
        // #250 : `tri-gui <image>` ouvre le dossier de l'image, sur elle.
        let dir = tempfile::tempdir().unwrap();
        let photos = dir.path().join("photos");
        std::fs::create_dir(&photos).unwrap();
        for name in ["a.jpg", "b.jpg", "c.jpg"] {
            image::RgbImage::new(8, 8).save(photos.join(name)).unwrap();
        }
        let mut s = AppSettings::default();
        s.cache.dir = Some(dir.path().join("cache"));
        s.data.dir = Some(dir.path().join("data"));
        s.places.watch_ms = 0;
        s.gui.reopen_last = false;
        let image = photos.join("b.jpg");
        let mut h = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(Some(image), s, None));
        run_until(&mut h, |app| app.loading.is_none() && app.files.len() == 3);
        assert_eq!(h.state().folder.dir, photos);
        assert_eq!(selected_name(&h), "b.jpg");
        assert_eq!(h.state().mode, Mode::View, "ouverte en plein écran");
        h.run_steps(2);
        assert!(
            h.state().focus_mode,
            "mode concentration ([gui] image_focus)"
        );
        // `--focus` sur un dossier : mode concentration aussi, en grille.
        let mut s = AppSettings::default();
        s.cache.dir = Some(dir.path().join("cache"));
        s.data.dir = Some(dir.path().join("data"));
        s.places.watch_ms = 0;
        s.gui.reopen_last = false;
        let folder = photos.clone();
        let mut f = Harness::builder()
            .with_size(vec2(1000.0, 700.0))
            .build_eframe(move |_cc| TriApp::new(Some(folder), s, None).with_focus(true));
        run_until(&mut f, |app| app.loading.is_none());
        assert_eq!(f.state().mode, Mode::Grid);
        assert!(f.state().focus_mode, "--focus");
    }

