    #[test]
    fn help_search_finds_english_words_and_forgives_typos() {
        let km = crate::actions::Keymap::default()
            .with_leader("Ctrl+b")
            .unwrap();
        let first = |q: &str| help_rows(&km, q).first().map(|(a, _)| *a);
        let found = |q: &str, a: Action| help_rows(&km, q).iter().any(|(x, _)| *x == a);
        // Mots anglais dans une interface en français.
        assert!(found("crop", Action::Crop));
        assert!(found("peaking", Action::TogglePeaking));
        // Fautes de frappe.
        assert!(found("histrogramme", Action::ToggleHistogram));
        assert!(found("recardrer", Action::Crop));
        // Le mot juste reste devant.
        assert_eq!(first("recadrer"), Some(Action::Crop));
        // Les mots-clés du thème : « noter » trouve les étoiles, pas les lettres éparpillées.
        assert!(found("noter", Action::Stars(3)));
        assert!(help_rows(&km, "noter").len() < 30);
        // Trouvée dans le libellé avant les mots-clés.
        let darktable = first("darktable").expect("darktable");
        assert!(
            darktable.label().contains("Darktable"),
            "{}",
            darktable.label()
        );
    }

    #[test]
    fn typing_a_key_in_the_help_search_finds_its_actions_only() {
        let km = crate::actions::Keymap::default()
            .with_leader("Ctrl+b")
            .unwrap();
        let found =
            |q: &str| -> Vec<Action> { help_rows(&km, q).into_iter().map(|(a, _)| a).collect() };
        for query in ["cmd f", "Cmd+F", "cmd+f", "CMD F"] {
            let actions = found(query);
            assert!(actions.contains(&Action::Search), "{query}");
            assert!(actions.contains(&Action::FocusMode), "{query} : Cmd+Maj+f");
            assert_eq!(actions.len(), 2, "{query} : {actions:?}");
        }
        // Avec Maj : seulement Cmd+Maj+f.
        assert_eq!(found("cmd maj f"), [Action::FocusMode]);
        // Au moins ces modificateurs : Maj+p, et Cmd+Maj+p (la palette).
        assert_eq!(
            found("maj p"),
            [Action::Flag(tri::xmp::Flag::Accepted), Action::Palette]
        );
        // Pas une touche : la recherche par mots.
        assert!(found("cmd").len() > 2);
        assert!(found("netteté").contains(&Action::TogglePeaking));
    }

    #[test]
    fn the_loupe_and_the_zoom_toggle_and_escape_goes_back() {
        // 25/11/2026 (idée de l'utilisateur) : `z m` allume la loupe jusqu'à `z m` ou
        // Échap ; `z z` zoome, et zoomé, `z z` ou Échap ramènent d'où l'on venait.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let rows = help_rows(&h.state().keymap, "loupe");
        let keys = |a: Action| {
            rows.iter()
                .find(|(r, _)| *r == a)
                .map(|(_, k)| k.clone())
                .unwrap_or_default()
        };
        assert_eq!(keys(Action::Loupe), "zm", "{rows:?}");
        let z = |h: &mut Harness<'_, TriApp>, second: Key| {
            press(h, Key::Z, Modifiers::NONE);
            press(h, second, Modifiers::NONE);
        };
        // La loupe : allumée, éteinte par `z m` puis par Échap, sans quitter la grille.
        z(&mut h, Key::M);
        assert!(h.state().loupe_toggled);
        z(&mut h, Key::M);
        assert!(!h.state().loupe_toggled);
        z(&mut h, Key::M);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().loupe_toggled);
        assert_eq!(h.state().mode, Mode::Grid);
        // Allumée au clavier : sur la vignette sélectionnée, pas sous le pointeur
        // (retour du 25/11/2026), et les flèches la déplacent dedans.
        h.state_mut().gui.zoom.loupe_delay_ms = 0;
        run_until(&mut h, |app| app.grid_images.len() >= 3);
        let other = h
            .state()
            .grid_images
            .iter()
            .find(|(i, _)| *i == 2)
            .map(|(_, r)| r.center())
            .unwrap();
        h.state_mut().select(0);
        h.hover_at(other);
        h.run_steps(2);
        z(&mut h, Key::M);
        run_until(&mut h, |app| app.loupe_on);
        assert_eq!(h.state().loupe_index, 0, "la sélectionnée");
        let before = h.state().loupe_point.map(|(_, p)| p);
        for _ in 0..3 {
            press(&mut h, Key::ArrowRight, Modifiers::NONE);
            h.run_steps(2);
        }
        let after = h.state().loupe_point;
        assert_eq!(after.map(|(i, _)| i), Some(0));
        assert!(
            after.map(|(_, p)| p) != before,
            "déplacée : {before:?} → {after:?}"
        );
        assert_eq!(h.state().selected, 0, "la sélection ne bouge pas");
        press(&mut h, Key::Escape, Modifiers::NONE);
        // Le zoom depuis la grille : `z z` y ramène, Échap aussi.
        z(&mut h, Key::Z);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().zoom.is_some());
        z(&mut h, Key::Z);
        assert_eq!(h.state().mode, Mode::Grid);
        assert!(h.state().zoom.is_none());
        z(&mut h, Key::Z);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
        // Depuis le plein écran ajusté : retour à l'ajusté, puis Échap à la grille.
        act(&mut h, Action::Open);
        z(&mut h, Key::Z);
        assert!(h.state().zoom.is_some());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().zoom.is_none());
        z(&mut h, Key::Z);
        z(&mut h, Key::Z);
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert_eq!(h.state().mode, Mode::Grid);
    }

    #[test]
    fn help_opens_and_closes_with_its_keys() {
        let (mut h, _dir) = harness();
        h.run_steps(3);
        assert!(!h.state().help);
        // F1 ouvre et ferme ; une fois ouverte, la recherche a le focus et « ? » s'y tape.
        press(&mut h, Key::F1, Modifiers::NONE);
        assert!(h.state().help, "F1 doit ouvrir l'aide");
        press(&mut h, Key::F1, Modifiers::NONE);
        assert!(!h.state().help, "F1 doit refermer l'aide");
        // « ? », avec ou sans Maj selon le clavier : l'aide « ici », qui se referme pareil.
        for modifiers in [Modifiers::NONE, Modifiers::SHIFT] {
            press(&mut h, Key::Questionmark, modifiers);
            assert!(h.state().help_here.is_some(), "{modifiers:?}");
            press(&mut h, Key::Questionmark, modifiers);
            assert!(h.state().help_here.is_none(), "{modifiers:?}");
        }
    }

    #[test]
    fn f_s_and_f_r_change_the_order_and_keep_the_selection() {
        let (mut h, dir) = harness();
        h.run_steps(3);
        let photos = dir.path().join("photos");
        // img2 la plus ancienne, puis img0, puis img1.
        let now = std::time::SystemTime::now();
        for (name, hours) in [("img2.jpg", 3), ("img0.jpg", 2), ("img1.jpg", 1)] {
            std::fs::File::options()
                .write(true)
                .open(photos.join(name))
                .unwrap()
                .set_modified(now - Duration::from_secs(hours * 3600))
                .unwrap();
        }
        let order = |h: &Harness<'_, TriApp>| -> Vec<String> {
            h.state().files.iter().map(|f| file_name(&f.path)).collect()
        };
        assert_eq!(order(&h), ["img0.jpg", "img1.jpg", "img2.jpg"]);
        h.state_mut().select(1);
        // f r : décroissant, img1 toujours sélectionnée.
        // f r → Maj+N.
        press(&mut h, Key::N, Modifiers::SHIFT);
        assert_eq!(order(&h), ["img2.jpg", "img1.jpg", "img0.jpg"]);
        assert_eq!(
            file_name(&h.state().files[h.state().selected].path),
            "img1.jpg"
        );
        // f s deux fois : date de modification (décroissant : la plus récente d'abord).
        for _ in 0..2 {
            // f s → n.
            press(&mut h, Key::N, Modifiers::NONE);
        }
        assert_eq!(h.state().order.key, tri::sort::SortKey::Modified);
        assert_eq!(order(&h), ["img1.jpg", "img0.jpg", "img2.jpg"]);
        assert_eq!(
            file_name(&h.state().files[h.state().selected].path),
            "img1.jpg"
        );
        // f r → Maj+N (revue du 06/11/2026).
        press(&mut h, Key::N, Modifiers::SHIFT);
        assert_eq!(order(&h), ["img2.jpg", "img0.jpg", "img1.jpg"]);
        // Retenu d'un lancement à l'autre.
        assert_eq!(h.state().display().sort, Some(h.state().order));
    }

    #[test]
    fn backgrounds_rotate_without_repeating_the_theme() {
        use crate::settings::Color as C;
        let theme = Color32::from_rgb(12, 12, 12);
        let list = [
            C([48, 48, 48]),
            C([12, 12, 12]),
            C([0, 0, 0]),
            C([48, 48, 48]),
        ];
        let mut seen = vec![None];
        let mut current = None;
        for _ in 0..3 {
            current = next_background(current, theme, &list);
            seen.push(current);
        }
        // Le gris du thème et le doublon sautés : thème, gris foncé, noir, puis le thème.
        assert_eq!(
            seen,
            [None, Some(C([48, 48, 48])), Some(C([0, 0, 0])), None]
        );
        // Un fond choisi qui n'est plus proposé repart du début.
        assert_eq!(
            next_background(Some(C([1, 2, 3])), theme, &list),
            Some(C([48, 48, 48]))
        );
        assert_eq!(next_background(None, theme, &[]), None);
    }

    #[test]
    fn the_help_lists_the_command_line_and_copies_a_command() {
        // Issue n° 441 : les commandes à la suite des raccourcis, cherchées de même, et un
        // bouton qui copie l'exemple rempli avec le dossier ouvert.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::F1, Modifiers::NONE);
        let commands = |h: &Harness<'_, TriApp>| -> Vec<&'static str> {
            h.state()
                .help_lines
                .iter()
                .flat_map(|l| &l.lines)
                .filter_map(|l| match l {
                    HelpLine::Command(c) => Some(c.id),
                    _ => None,
                })
                .collect()
        };
        assert_eq!(commands(&h).len(), tri::commands::COMMANDS.len());
        // Une recherche : la commande qui y répond, avec son thème.
        h.state_mut().help_search = Some("décharge une carte".into());
        h.run_steps(3);
        assert_eq!(commands(&h).first(), Some(&"offload"), "{:?}", commands(&h));
        assert!(
            h.query_by_label("Ligne de commande : Déchargement")
                .is_some()
        );
        h.state_mut().help_search = Some("exposition de chaque image".into());
        h.run_steps(3);
        assert!(commands(&h).contains(&"exposure"), "{:?}", commands(&h));
        // L'exemple dans une ligne dépliée sous la commande.
        let copy = format!("{} exposure", t!("help-command-copy"));
        assert!(h.query_by_label(&copy).is_none());
        h.get_by_label(&format!("{} exposure", t!("help-command-example")))
            .click();
        h.run_steps(3);
        h.get_by_label(&copy).click();
        // Le texte copié est dans la sortie de l'image où le clic est vu.
        h.step();
        assert_eq!(h.state().notice, Some((t!("help-command-copied"), false)));
        let dir = tri::commands::shell_quote(&h.state().folder.dir);
        let copied = h
            .output()
            .platform_output
            .commands
            .iter()
            .find_map(|c| match c {
                egui::OutputCommand::CopyText(text) => Some(text.clone()),
                _ => None,
            });
        assert_eq!(copied, Some(format!("tri {dir} --exposure")));
    }

    #[test]
    fn help_search_filters_and_typing_is_not_a_shortcut() {
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::F1, Modifiers::NONE);
        assert!(h.query_by_label("Ligne du dessous").is_some());
        // Rangée par thème sans recherche : le thème dans la liste et en titre à droite.
        assert_eq!(h.query_all_by_label("Navigation").count(), 2);
        // Plus bas, hors de la vue (seules les lignes visibles sont dessinées) : dans la
        // liste préparée.
        let groups: Vec<&str> = h
            .state()
            .help_lines
            .iter()
            .flat_map(|l| &l.lines)
            .filter_map(|l| match l {
                HelpLine::Group(name) => Some(name.as_str()),
                HelpLine::Action { .. }
                | HelpLine::Command(_)
                | HelpLine::Example(_)
                | HelpLine::Field(_) => None,
            })
            .collect();
        assert!(groups.contains(&"Notation"), "{groups:?}");
        for c in "wqx".chars() {
            h.event(UiEvent::Text(c.to_string()));
            h.run_steps(1);
        }
        h.run_steps(2);
        assert!(!h.state().quit_requested, "« q » tapé dans la recherche");
        assert!(h.state().help);
        assert_eq!(h.state().help_search.as_deref(), Some("wqx"));
        // « wqx » ne correspond à rien.
        assert!(h.query_by_label("Aucune action ne correspond.").is_some());
        // « pandos » plutôt que « pnd » (31/10/2026) : avec les actions des piles et des
        // développements, « pnd » trouve trop de lignes et celle-ci sort de la zone visible.
        h.state_mut().help_search = Some("pandos".into());
        h.run_steps(2);
        assert!(
            h.query_by_label("Afficher / masquer le panneau des dossiers")
                .is_some()
        );
        assert!(h.query_by_label("Ligne du dessous").is_none());
        // Refermer puis rouvrir : recherche vide.
        press(&mut h, Key::Escape, Modifiers::NONE);
        press(&mut h, Key::F1, Modifiers::NONE);
        assert_eq!(h.state().help_search.as_deref(), Some(""));
    }

