    #[test]
    fn a_card_is_offloaded_from_the_folder_panel() {
        let (mut h, dir) = harness();
        // Fausse carte : deux JPEG dans DCIM.
        let card = dir.path().join("CARTE");
        std::fs::create_dir_all(card.join("DCIM/100_TEST")).unwrap();
        for i in 0..2 {
            image::RgbImage::from_pixel(32, 24, image::Rgb([90, 90, 90]))
                .save(card.join(format!("DCIM/100_TEST/IMG{i}.jpg")))
                .unwrap();
        }
        h.state_mut().tree = Tree::with_places(
            vec![tri::places::Place {
                name: "CARTE".into(),
                path: card.clone(),
                kind: tri::places::PlaceKind::Volume,
            }],
            false,
        );
        h.run_steps(2);
        h.get_by_label("Décharger la carte…").click();
        let deadline = Instant::now() + Duration::from_secs(20);
        let wait_for = |h: &mut Harness<'_, TriApp>, label: &str| {
            while h.query_by_label(label).is_none() {
                assert!(Instant::now() < deadline, "jamais vu : {label}");
                h.run_steps(1);
                std::thread::sleep(Duration::from_millis(10));
            }
        };
        wait_for(&mut h, "Décharger");
        assert!(h.query_by_label_contains("2 à copier").is_some());
        // Destination sur un disque interne : « garder les données de tri » proposé pour
        // la séance, pas coché d'office (issue n° 378).
        assert!(
            h.query_by_label("Garder les données de tri dans le dossier de la séance")
                .is_some()
        );
        // « Ouvrir le dossier à la fin » est coché par défaut ; « RAW seulement » non.
        settle_dialog(&mut h);
        h.get_by_label("Décharger").click();
        while h
            .query_by_label_contains("2 fichiers copiés et vérifiés")
            .is_none()
        {
            assert!(Instant::now() < deadline, "jamais copiés");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        h.run_steps(3);
        assert!(
            h.query_by_label_contains("2 fichiers copiés et vérifiés")
                .is_some()
        );
        let opened = h.state().folder.dir.clone();
        assert!(
            opened.starts_with(dir.path().join("photos-local")),
            "{opened:?}"
        );
        assert_eq!(
            names(&h),
            ["IMG0.jpg", "IMG1.jpg"],
            "séance ouverte d'elle-même, à plat"
        );
        assert!(h.state().offload.is_some(), "le bilan reste affiché");
        assert!(h.state().ejecting.is_none(), "éjection non cochée : rien");
        h.get_by_label("Fermer").click();
        h.run_steps(2);
        assert!(h.state().offload.is_none());
        let remembered = std::fs::read_to_string(dir.path().join("data/offload-root")).unwrap();
        assert!(
            remembered.ends_with("photos-local"),
            "racine mémorisée : {remembered}"
        );
        assert!(
            opened
                .file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with("20"),
            "nom de séance sans dossier d'année : {opened:?}"
        );
        assert_eq!(opened.parent().unwrap(), dir.path().join("photos-local"));
        let history = std::fs::read_to_string(dir.path().join("history.tsv")).unwrap();
        assert_eq!(history.lines().count(), 2, "historique écrit");
        assert!(!tri::store::kept(&opened), "rien gardé à côté des photos");
        assert!(!opened.join(tri::store::DIR).exists());
        // Rouverte : les deux images déjà déchargées sont ignorées (retour du 12/11/2026) ;
        // « décharger à nouveau » coché, elles sont de nouveau à copier.
        h.get_by_label("Décharger la carte…").click();
        let deadline = Instant::now() + Duration::from_secs(20);
        while h.query_by_label("Décharger").is_none() {
            assert!(Instant::now() < deadline, "boîte jamais rouverte");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(
            h.query_by_label_contains("2 images : 2 déjà déchargées, 0 nouvelle ; 0 à copier")
                .is_some(),
            "déjà déchargées"
        );
        click_settled(&mut h, "Décharger à nouveau les 2 images déjà déchargées");
        h.run_steps(3);
        // Cochée : plus ignorées par l'historique ; le nom proposé revient au même
        // dossier, où elles sont déjà : annoncées comme telles.
        assert!(
            h.query_by_label_contains("2 déjà dans la destination")
                .is_some()
        );
        assert!(
            h.query_by_label_contains("0 nouvelle, 2 déjà dans la destination ; 0 à copier")
                .is_some()
        );
        h.get_by_label("Annuler").click();
        h.run_steps(2);
    }

    #[test]
    fn a_full_destination_brings_the_offload_back_until_answered() {
        // 12/11/2026 : destination pleine, le déchargement échouait sans rien dire. La copie
        // (ici en arrière-plan) s'arrête, la boîte revient avec ce qui est fait et ce qui
        // reste, et y reste, sans limite de temps, jusqu'à « Réessayer » ou « Abandonner ».
        let (mut h, dir) = harness();
        let card = dir.path().join("CARTE");
        std::fs::create_dir_all(&card).unwrap();
        let ctx = h.ctx.clone();
        let mut dialog = OffloadDialog::new(
            card,
            CENTRED,
            h.state().settings.offload.clone(),
            None,
            &ctx,
        );
        let answers = dialog.simulate_full(tri::offload::OutOfSpace {
            destination: dir.path().join("dest"),
            file: dir.path().join("CARTE/B.RAF"),
            copied: 12,
            left: 30,
            needed: 900_000_000,
            free: Some(4_000_000),
        });
        h.state_mut().offload = Some(dialog);
        h.run_steps(3);
        let dialog = h.state().offload.as_ref().expect("toujours là");
        assert!(!dialog.is_hidden(), "revenue au premier plan");
        assert!(dialog.asks_full());
        assert!(h.query_by_label("Destination pleine").is_some());
        // Court, en une ligne (retour du 18/11/2026).
        assert!(
            h.query_by_label_contains(
                "12 fichiers copiés et vérifiés, 30 restent à copier (858 Mo), 3,8 Mo libres"
            )
            .is_some()
        );
        // Échap ne la ferme pas : il faut choisir.
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(3);
        assert!(h.state().offload.as_ref().is_some_and(|d| !d.is_hidden()));
        click_settled(&mut h, "Réessayer");
        h.run_steps(2);
        assert_eq!(answers.try_recv(), Ok(true), "réessayer");
        assert!(!h.state().offload.as_ref().unwrap().asks_full());
        // Toujours pleine : la question revient ; « Abandonner » arrête la copie.
        let answers =
            h.state_mut()
                .offload
                .as_mut()
                .unwrap()
                .simulate_full(tri::offload::OutOfSpace {
                    destination: dir.path().join("dest"),
                    file: dir.path().join("CARTE/B.RAF"),
                    copied: 12,
                    left: 30,
                    needed: 900_000_000,
                    free: Some(0),
                });
        h.run_steps(3);
        click_settled(&mut h, "Abandonner");
        h.run_steps(2);
        assert_eq!(answers.try_recv(), Ok(false), "abandonner");
    }

