    #[test]
    fn an_offload_can_group_the_pairs_of_the_session() {
        // Issue n° 392 : une carte avec des paires RAW+JPEG ; la case « Regrouper RAW et
        // JPEG » cochée, la séance s'ouvre regroupée, sans question.
        let (mut h, dir) = harness();
        h.state_mut().settings.files.group_pairs = tri::pairs::Grouping::Ask;
        let card = dir.path().join("CARTE");
        let shots = card.join("DCIM/100_TEST");
        std::fs::create_dir_all(&shots).unwrap();
        image::RgbImage::from_pixel(32, 24, image::Rgb([90, 90, 90]))
            .save(shots.join("IMG0.jpg"))
            .unwrap();
        std::fs::write(shots.join("IMG0.RAF"), b"raw").unwrap();
        h.state_mut().tree = Tree::with_places(
            vec![tri::places::Place {
                name: "CARTE".into(),
                path: card.clone(),
                kind: tri::places::PlaceKind::Volume,
            }],
            false,
        );
        h.run_steps(2);
        h.get_by_label("Décharger la carte…").click();
        let deadline = Instant::now() + Duration::from_secs(20);
        while h.query_by_label("Décharger").is_none() {
            assert!(Instant::now() < deadline, "boîte jamais prête");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(
            h.query_by_label("Regrouper RAW et JPEG (une paire)")
                .is_some()
        );
        h.state_mut().offload.as_mut().unwrap().pairs_choice = Some(true);
        settle_dialog(&mut h);
        // #469 : « RAW seulement » grisée tant que les paires sont regroupées.
        {
            use egui_kittest::kittest::NodeT;
            let raw_only = t!("offload-raw-only");
            assert!(
                h.get_by_label(&raw_only).accesskit_node().is_disabled(),
                "RAW seulement grisée"
            );
        }
        h.get_by_label("Décharger").click();
        while h
            .query_by_label_contains("2 fichiers copiés et vérifiés")
            .is_none()
        {
            assert!(Instant::now() < deadline, "jamais copié");
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        h.run_steps(3);
        let opened = h.state().folder.dir.clone();
        let data = h.state().settings.data_dir();
        assert_eq!(tri::pairs::decided(data.as_deref(), &opened), Some(true));
        assert!(h.state().pairs_view(), "la séance regroupée");
        assert!(h.state().pairs_dialog.is_none(), "pas de question");
    }

    #[test]
    fn a_deleted_subfolder_leaves_the_list() {
        // Retour du 25/10/2026 : « Sous-dossiers » coché, un sous-dossier supprimé : ses
        // images quittent la liste (leurs calculs s'arrêtent avec).
        let (mut h, _dir) = harness();
        let folder = h.state().folder.dir.clone();
        let sub = folder.join("sous");
        std::fs::create_dir(&sub).unwrap();
        image::RgbImage::new(16, 16)
            .save(sub.join("x.jpg"))
            .unwrap();
        h.state_mut().subfolders = true;
        h.state_mut().reload_folder(None);
        h.run_steps(2);
        assert_eq!(h.state().files.len(), 4);
        tri::files::delete_dir(&sub, false).unwrap();
        h.state_mut().after_folder_change(None, Some(sub));
        assert_eq!(h.state().files.len(), 3, "images du sous-dossier retirées");
    }

    #[test]
    fn background_tasks_share_one_bar() {
        // Issue n° 36 : plusieurs tâches, une barre globale en bas du panneau des
        // métadonnées ; un clic déplie le détail. Panneau masqué : dans la barre d'état.
        let (mut h, _dir) = harness();
        run_until(&mut h, |app| {
            app.engine
                .as_ref()
                .unwrap()
                .scheduler
                .wait_idle(Duration::ZERO)
        });
        h.run_steps(3);
        let app = h.state_mut();
        app.gui.progress_hide_done = true;
        app.progress_hidden_until = None;
        app.progress[0] = Progress { done: 1, total: 4 };
        app.progress[3] = Progress { done: 3, total: 4 };
        h.run_steps(2);
        let global = t!("tasks-global", n = 2, percent = "50");
        assert!(
            h.query_by_label_contains(&global).is_some(),
            "une barre globale"
        );
        assert!(h.query_by_label_contains("1/4").is_none(), "détail replié");
        let folded = h.state().tasks_height;
        assert!(folded > 0.0, "panneau des tâches");
        h.get_by_label_contains(&global).click();
        h.run_steps(3);
        assert!(h.state().tasks_open);
        assert!(h.query_by_label_contains("1/4").is_some(), "détail déplié");
        // La fine barre reste à sa place : un second clic replie (retour du 25/10/2026).
        h.get_by_label_contains(&global).click();
        h.run_steps(3);
        assert!(!h.state().tasks_open);
        assert!(
            h.query_by_label_contains("1/4").is_none(),
            "replié de nouveau"
        );
        // Sa hauteur d'avant : pas un grand fond vide au-dessus de la barre (#158).
        assert_eq!(h.state().tasks_height, folded);
        // Panneau des métadonnées masqué : la barre globale passe dans la barre d'état.
        h.state_mut().metadata_panel = false;
        h.run_steps(3);
        assert!(h.query_by_label_contains(&global).is_some());
    }

    #[test]
    fn the_star_filter_compares_at_least_exactly_or_at_most() {
        // #165 : pas seulement « au moins » ; `f =` ou le bouton ≥ / = / ≤.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        for (i, key) in [Key::Num3, Key::Num4, Key::Num5].into_iter().enumerate() {
            h.state_mut().select(i);
            press(&mut h, key, Modifiers::NONE);
        }
        let count = |h: &Harness<'_, TriApp>| h.state().files.len();
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::Num4, Modifiers::NONE);
        assert_eq!(count(&h), 2, "au moins 4");
        press(&mut h, Key::F, Modifiers::NONE);
        type_text(&mut h, "=");
        assert_eq!(count(&h), 1, "exactement 4");
        assert!(h.state().filter_summary().contains("exactement 4"));
        h.get_by_label("=").click();
        h.run_steps(2);
        assert_eq!(count(&h), 2, "au plus 4");
        assert!(h.state().filter_summary().contains("4 étoiles ou moins"));
        h.get_by_label("≤").click();
        h.run_steps(2);
        assert_eq!(h.state().stars_op, tri::notes::StarsOp::AtLeast);
        assert_eq!(count(&h), 2, "au moins 4, de nouveau");
    }

    #[test]
    fn ratings_step_and_the_filter_takes_the_highest() {
        // 25/11/2026 : `m l` / `m h` une étoile de plus / de moins, `m k` / `m j` la
        // couleur suivante / précédente ; `f *` et `f Maj+O` (ou les boutons) filtrent sur
        // la plus haute, la comparaison gardée.
        use tri::xmp::Color;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let notes = |h: &Harness<'_, TriApp>, i: usize| {
            let path = h.state().files[i].path.clone();
            h.state().folder.notes.notes(&path).clone()
        };
        let seq = |h: &mut Harness<'_, TriApp>, second: Key| {
            press(h, Key::M, Modifiers::NONE);
            press(h, second, Modifiers::NONE);
        };
        h.state_mut().select(0);
        seq(&mut h, Key::L);
        seq(&mut h, Key::L);
        seq(&mut h, Key::L);
        seq(&mut h, Key::H);
        assert_eq!(notes(&h, 0).stars, 2);
        seq(&mut h, Key::K);
        seq(&mut h, Key::K);
        assert_eq!(notes(&h, 0).colors, [Color::Yellow], "rouge puis jaune");
        h.state_mut().select(1);
        // À la souris : les chevrons de la barre de notation.
        h.get_by_label(&Action::StarsStep(true).label()).click();
        h.run_steps(2);
        h.get_by_label(&Action::ColorStep(true).label()).click();
        h.run_steps(2);
        assert_eq!(notes(&h, 1).stars, 1);
        assert_eq!(notes(&h, 1).colors, [Color::Red]);
        seq(&mut h, Key::J);
        assert!(
            notes(&h, 1).colors.is_empty(),
            "sous le rouge : sans couleur"
        );
        seq(&mut h, Key::K);
        let total = h.state().files.len();
        let count = |h: &Harness<'_, TriApp>| h.state().files.len();
        // Le plus haut : 2 étoiles, « au moins » gardé.
        press(&mut h, Key::F, Modifiers::NONE);
        type_text(&mut h, "*");
        assert_eq!(
            h.state().notes_rule.stars,
            Some(tri::notes::StarsRule::AtLeast(2))
        );
        assert_eq!(count(&h), 1);
        // « Exactement » : la comparaison reste, seul le nombre suit (1 étoile au plus
        // haut une fois la première image redescendue).
        h.state_mut().stars_op = tri::notes::StarsOp::Exactly;
        act(&mut h, Action::FilterStars(1));
        assert_eq!(count(&h), 1, "exactement 1");
        h.get_by_label(&Action::FilterStarsTop.label()).click();
        h.run_steps(2);
        assert_eq!(
            h.state().notes_rule.stars,
            Some(tri::notes::StarsRule::Exactly(2)),
            "le plus haut cherché sans le filtre en cours"
        );
        act(&mut h, Action::FilterStars(0));
        assert_eq!(count(&h), total);
        // Couleurs : jaune est la plus haute (rouge, jaune, vert…).
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::O, Modifiers::SHIFT);
        assert_eq!(
            h.state()
                .notes_rule
                .colors
                .as_ref()
                .map(|r| r.any_of.clone()),
            Some(vec![Color::Yellow])
        );
        assert_eq!(count(&h), 1);
        // Sans étoile ni couleur nulle part : rien ne change, et c'est dit.
        act(&mut h, Action::FilterClear);
        for i in 0..2 {
            h.state_mut().select(i);
            act(&mut h, Action::Stars(0));
            act(&mut h, Action::ColorStep(false));
            act(&mut h, Action::ColorStep(false));
        }
        act(&mut h, Action::FilterStarsTop);
        assert_eq!(h.state().notes_rule.stars, None);
        assert_eq!(count(&h), total);
        act(&mut h, Action::FilterColorTop);
        assert_eq!(h.state().notes_rule.colors, None);
    }

