    #[test]
    fn adjustments_sidecars_and_watch_settings_apply_at_once() {
        // Retour du 11/11/2026 : `[adjust] auto_exposure_bias` changé dans la fenêtre de
        // réglages n'avait d'effet qu'au prochain lancement (la section n'était pas
        // recopiée), alors qu'elle n'est pas marquée « au prochain lancement ».
        let (mut h, _dir) = harness();
        let mut new = AppSettings {
            gui: h.state().gui.clone(),
            ..AppSettings::default()
        };
        new.adjust.auto_exposure_bias = -1.0;
        new.watch.interval_ms = 1234;
        let ctx = h.ctx.clone();
        h.state_mut().apply_settings(&ctx, new);
        assert_eq!(h.state().settings.adjust.auto_exposure_bias, -1.0);
        assert_eq!(h.state().settings.watch.interval_ms, 1234);
        for section in ["adjust", "sidecars", "watch"] {
            assert!(
                !crate::settings_window::needs_restart(section, ""),
                "{section} : appliquée tout de suite"
            );
        }
    }

    #[test]
    fn the_histogram_shows_the_image_after_its_adjustments() {
        // #420 (11/11/2026) : réel par défaut, « après réglages » au bouton ou à `e`
        // (`after_auto`, le réglage de la case aussi) ; pendant le glissement, la dernière
        // mesure décalée tout de suite ; badges qui suivent avec
        // `badges_follow_adjustments`.
        let (mut h, dir) = harness();
        // `e` écrit le réglage : dans un fichier du test, jamais la vraie configuration.
        let config = dir.path().join("config.toml");
        std::fs::write(&config, "").unwrap();
        h.state_mut().config_path = Some(config);
        let path = h.state().files[0].path.clone();
        run_until(&mut h, |app| app.exposures.contains(&path));
        let real = h.state_mut().shown_exposure(0).unwrap();
        assert!(real.1.is_none(), "réel par défaut");
        let set_exposure = |h: &mut Harness<'_, TriApp>, ev: f32| {
            let mut layers = tri::adjust::Layers::default();
            layers.correction.exposure = ev;
            h.state()
                .adjust_map
                .write()
                .unwrap()
                .layers
                .insert(path.clone(), layers);
        };
        set_exposure(&mut h, 2.0);
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::HistogramAfter);
        assert!(h.state().gui.histogram.after_auto);
        // La mesure arrive en fond, réglages compris.
        let measured = |app: &TriApp| {
            app.afters
                .get(&path)
                .is_some_and(|a| a.layers.is_some_and(|l| l.correction.exposure == 2.0))
        };
        run_until(&mut h, |app| app.after_pending.is_empty() && measured(app));
        let (after, sensor) = h.state_mut().shown_exposure(0).unwrap();
        let sensor = sensor.expect("avec les données réelles à côté");
        assert!(
            after.over_fraction() > sensor.over_fraction(),
            "+2 IL : plus de saturés ({} / {})",
            after.over_fraction(),
            sensor.over_fraction()
        );
        // Glissement : la mesure n'est pas refaite, la dernière est décalée tout de suite.
        set_exposure(&mut h, -2.0);
        let (live, _) = h.state_mut().shown_exposure(0).unwrap();
        assert!(measured(h.state()), "dernière mesure encore à +2 IL");
        assert!(
            live.over_fraction() < after.over_fraction(),
            "décalée vers le sombre : {} / {}",
            live.over_fraction(),
            after.over_fraction()
        );
        run_until(&mut h, |app| app.after_pending.is_empty() && !measured(app));
        // `e` dans le grand histogramme rebascule sur le réel.
        press(&mut h, Key::G, Modifiers::NONE);
        press(&mut h, Key::I, Modifiers::NONE);
        press(&mut h, Key::E, Modifiers::NONE);
        assert!(!h.state().gui.histogram.after_auto, "e : retour au réel");
        assert!(h.state_mut().shown_exposure(0).unwrap().1.is_none());
        // Badges : sur le réel, sauf s'ils suivent les réglages.
        set_exposure(&mut h, 3.0);
        let far = Instant::now() + Duration::from_secs(5);
        let (real_over, _) = h.state_mut().clip_fractions(0, far).unwrap();
        h.state_mut().gui.histogram.badges_follow_adjustments = true;
        let (follow_over, _) = h.state_mut().clip_fractions(0, far).unwrap();
        assert!(
            follow_over > real_over,
            "+3 IL : badge saturé ({follow_over} / {real_over})"
        );
    }

    #[test]
    fn the_adjustments_section_has_the_after_histogram_checkbox() {
        // Retour du 11/11/2026 : la case « Histogramme après réglages » en tête de la
        // section Réglages (plus clair que la boîte de l'histogramme), écrite dans la
        // configuration ([gui.histogram] after_auto).
        let (mut h, dir) = harness();
        let config = dir.path().join("config.toml");
        std::fs::write(&config, "").unwrap();
        h.state_mut().config_path = Some(config.clone());
        h.run_steps(3);
        h.get_by_label("Histogramme après réglages");
        assert!(!h.state().gui.histogram.after_auto, "décochée par défaut");
        h.state_mut().set_histogram_after_auto(true);
        assert!(h.state().gui.histogram.after_auto);
        let text = std::fs::read_to_string(&config).unwrap();
        let written: AppSettings = tri::settings::parse(&text).unwrap();
        assert!(written.gui.histogram.after_auto, "écrite : {text}");
        // Retour du 12/11/2026 : le bouton du grand histogramme (et `e`) est le même
        // réglage : la case cochée, il ramène l'avant, et la case le suit.
        let ctx = h.ctx.clone();
        h.state_mut().perform(&ctx, Action::HistogramAfter);
        assert!(
            !h.state().gui.histogram.after_auto,
            "le bouton décoche la case"
        );
        let text = std::fs::read_to_string(&config).unwrap();
        let written: AppSettings = tri::settings::parse(&text).unwrap();
        assert!(!written.gui.histogram.after_auto, "écrite : {text}");
        h.state_mut().perform(&ctx, Action::HistogramAfter);
        assert!(h.state().gui.histogram.after_auto, "et la recoche");
    }

    #[test]
    fn one_section_open_folds_the_others() {
        // Retour du 11/11/2026 : `[gui] one_section_open` (désactivé par défaut) : déplier
        // une section replie les autres du même panneau ; l'histogramme, lui, est en haut
        // du panneau de droite, toujours visible.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        h.get_by_label("HISTOGRAMME");
        assert!(
            h.query_all_by_label("Replier").count() > 0,
            "des sections repliables"
        );
        // Par défaut : plusieurs sections dépliées.
        h.state_mut().unfold_side_section("exif");
        assert!(!h.state().panel_folded.contains("filters"));
        // L'option allumée : chaque panneau garde une section, ici la dernière dépliée.
        h.state_mut().gui.one_section_open = true;
        h.run_steps(1);
        for other in SIDE_SECTIONS.iter().filter(|&&s| s != "exif") {
            assert!(
                h.state().panel_folded.contains(*other),
                "{other} repliée d'emblée"
            );
        }
        let open_folders = |app: &TriApp| {
            app.tree
                .sections()
                .into_iter()
                .filter(|&s| !app.tree.is_folded(s))
                .count()
        };
        assert!(open_folders(h.state()) <= 1, "une section de dossiers");
        h.state_mut().unfold_side_section("filters");
        h.state_mut().unfold_side_section("exif");
        for other in SIDE_SECTIONS.iter().filter(|&&s| s != "exif") {
            assert!(h.state().panel_folded.contains(*other), "{other} repliée");
        }
        assert!(!h.state().panel_folded.contains("exif"));
        // Panneau des dossiers : pareil.
        let sections = h.state().tree.sections();
        if let [first, second, ..] = sections.as_slice() {
            h.state_mut().fold_folder_section(*second, false);
            h.state_mut().fold_folder_section(*first, false);
            assert!(h.state().tree.is_folded(*second));
            assert!(!h.state().tree.is_folded(*first));
        }
    }

    #[test]
    fn the_large_histogram_opens_and_closes() {
        let (mut h, _dir) = harness();
        press(&mut h, Key::G, Modifiers::NONE);
        press(&mut h, Key::I, Modifiers::NONE);
        assert!(h.state().histogram_large, "g i l'ouvre");
        // L'échelle est une icône dans l'histogramme (19/10/2026), plus un bouton texte
        // à côté de « Fermer ».
        assert!(h.query_by_label("Échelle linéaire").is_none());
        // p : photo d'analyse affichée / masquée (masquée par défaut).
        assert!(!h.state().histogram_photo);
        press(&mut h, Key::P, Modifiers::NONE);
        assert!(h.state().histogram_photo, "p la montre");
        press(&mut h, Key::P, Modifiers::NONE);
        assert!(!h.state().histogram_photo, "p la masque");
        // j : la courbe du JPEG boîtier (28/10/2026), retenue d'une session à l'autre.
        assert!(h.state().histogram_camera, "montrée par défaut");
        press(&mut h, Key::J, Modifiers::NONE);
        assert!(!h.state().histogram_camera, "j la masque");
        assert_eq!(h.state().display().histogram_camera, Some(false));
        press(&mut h, Key::J, Modifiers::NONE);
        assert!(h.state().histogram_camera, "j la remontre");
        // l : la luminance seule (28/10/2026) ; a revient aux trois canaux.
        press(&mut h, Key::L, Modifiers::NONE);
        assert_eq!(h.state().histogram_channel, Some(tri::exposure::LUMINANCE));
        press(&mut h, Key::A, Modifiers::NONE);
        assert_eq!(h.state().histogram_channel, None);
        leader(
            &mut h,
            &[(Key::I, Modifiers::NONE), (Key::S, Modifiers::NONE)],
        );
        assert_eq!(
            h.state().histogram_scale,
            HistogramScale::Linear,
            "<leader> i s dans la boîte"
        );
        // s seul, et c le canal suivant, dans la boîte (retour du 06/11/2026).
        press(&mut h, Key::S, Modifiers::NONE);
        assert_ne!(h.state().histogram_scale, HistogramScale::Linear, "s");
        assert!(h.state().histogram_large, "s ne ferme pas la boîte");
        let stacking = h.state().stacking;
        press(&mut h, Key::C, Modifiers::NONE);
        assert_eq!(h.state().histogram_channel, Some(0), "c : canal suivant");
        assert_eq!(h.state().stacking, stacking, "s n'a pas touché aux piles");
        assert!(h.state().crop.is_none(), "c ne recadre pas");
        // Les déplacements passent sous la boîte : l'histogramme suit l'image courante.
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(h.state().selected, 1, "→ : image suivante");
        assert!(h.state().histogram_large, "boîte toujours ouverte");
        press(&mut h, Key::ArrowLeft, Modifiers::NONE);
        assert_eq!(h.state().selected, 0, "h aussi");
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().histogram_large, "Échap la ferme");
        assert_eq!(h.state().mode, Mode::Grid);
        // Depuis le 23/11/2026, « g i » l'ouvre ; dedans, `g` est le canal vert (comme
        // `r g b a l`) : Échap la ferme.
        press(&mut h, Key::G, Modifiers::NONE);
        press(&mut h, Key::I, Modifiers::NONE);
        assert!(h.state().histogram_large);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().histogram_large, "Échap la ferme");
    }

    #[test]
    fn typing_in_a_text_field_triggers_no_shortcut() {
        let (mut h, dir) = harness();
        let card = dir.path().join("CARTE");
        std::fs::create_dir_all(card.join("DCIM")).unwrap();
        image::RgbImage::new(8, 8)
            .save(card.join("DCIM/A.jpg"))
            .unwrap();
        h.state_mut().tree = Tree::with_places(
            vec![tri::places::Place {
                name: "CARTE".into(),
                path: card,
                kind: tri::places::PlaceKind::Volume,
            }],
            false,
        );
        h.run_steps(2);
        h.get_by_label("Décharger la carte…").click();
        let deadline = Instant::now() + Duration::from_secs(20);
        while h.query_by_label("Décharger").is_none() {
            assert!(Instant::now() < deadline);
            h.run_steps(1);
            std::thread::sleep(Duration::from_millis(10));
        }
        // Clic dans le champ du dossier de la séance, puis « q » et « 3 ».
        h.ctx
            .memory_mut(|m| m.request_focus(crate::offload::folder_field_id()));
        h.run_steps(2);
        assert!(h.ctx.egui_wants_keyboard_input(), "le champ a le focus");
        press(&mut h, Key::Q, Modifiers::NONE);
        press(&mut h, Key::Num3, Modifiers::NONE);
        assert!(!h.state().quit_requested, "« q » n'a pas quitté");
        let photos = dir.path().join("photos");
        assert_eq!(
            tri::xmp::read(&photos.join("img0.jpg")).unwrap().stars,
            0,
            "« 3 » n'a pas noté"
        );
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(2);
    }

