    #[test]
    fn the_export_file_name_is_a_template_remembered_per_preset() {
        // #485 : un champ « Nom » sous le dossier, le gabarit tel quel ; un autre que
        // celui du préréglage est retenu pour lui ; le compteur suit l'ordre de la grille.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let name = |h: &Harness<'static, TriApp>| -> String {
            match &h.state().file_dialog {
                Some(crate::files::FileDialog::Export(d)) => d.name_input().to_string(),
                _ => panic!("boîte d'export attendue"),
            }
        };
        let out = dir.path().join("sortie");
        let typed = |h: &mut Harness<'static, TriApp>, folder: &str, template: &str| {
            if let Some(crate::files::FileDialog::Export(d)) = &mut h.state_mut().file_dialog {
                d.type_folder(folder);
                d.type_name(template);
            }
            h.run_steps(2);
        };
        // Toutes les images, dans l'ordre de la grille.
        press(&mut h, Key::A, CMD);
        press(&mut h, Key::E, CMD);
        assert_eq!(name(&h), "{name}", "le gabarit du préréglage");
        assert!(h.query_by_label(&t!("export-name")).is_some());
        // `{source}` est un dossier : dit en rouge, l'export refusé.
        typed(&mut h, &out.to_string_lossy(), "{source}");
        assert!(h.query_by_label_contains("n'a pas de sens ici").is_some());
        typed(&mut h, &out.to_string_lossy(), "serie_{n:2}");
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.notice.is_some()
        });
        let mut written: Vec<String> = std::fs::read_dir(&out)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        written.sort();
        assert_eq!(written, ["serie_01.jpg", "serie_02.jpg", "serie_03.jpg"]);
        // img0 est la première de la grille (copiée telle quelle).
        assert_eq!(
            std::fs::read(out.join("serie_01.jpg")).unwrap(),
            std::fs::read(dir.path().join("photos/img0.jpg")).unwrap()
        );
        assert_eq!(
            std::fs::read(out.join("serie_03.jpg")).unwrap(),
            std::fs::read(dir.path().join("photos/img2.jpg")).unwrap()
        );
        assert_eq!(h.state().export_names.len(), 1);
        assert_eq!(
            h.state().display().export_names.unwrap().len(),
            1,
            "gardé dans gui-state.toml"
        );
        press(&mut h, Key::E, CMD);
        assert_eq!(name(&h), "serie_{n:2}", "retenu");
    }

    #[test]
    fn the_export_folder_is_a_template_remembered_per_preset() {
        // Retour du 14/11/2026 : tout est dans le champ (plus de ligne « Destination »
        // dessous), un gabarit (#480) ; un dossier choisi est retenu pour son préréglage.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let dialog = |h: &Harness<'static, TriApp>| -> String {
            match &h.state().file_dialog {
                Some(crate::files::FileDialog::Export(d)) => d.input().to_string(),
                _ => panic!("boîte d'export attendue"),
            }
        };
        press(&mut h, Key::E, CMD);
        // Le gabarit du préréglage, explicite (#480) : `{source}/export`.
        assert_eq!(dialog(&h), "{source}/export");
        assert!(h.query_by_label_contains("Destination").is_none());
        // Un autre dossier : l'export y va, et il est retenu.
        let elsewhere = dir.path().join("ailleurs");
        if let Some(crate::files::FileDialog::Export(d)) = &mut h.state_mut().file_dialog {
            d.type_folder(&elsewhere.to_string_lossy());
        }
        h.run_steps(1);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.notice.is_some()
        });
        assert!(elsewhere.join("img0.jpg").is_file());
        assert_eq!(h.state().export_folders.len(), 1);
        assert_eq!(
            h.state().display().export_folders.unwrap().len(),
            1,
            "gardé dans gui-state.toml"
        );
        press(&mut h, Key::E, CMD);
        assert_eq!(dialog(&h), elsewhere.to_string_lossy(), "retenu");
        // Un compteur n'a pas de sens dans un dossier : dit en rouge.
        if let Some(crate::files::FileDialog::Export(d)) = &mut h.state_mut().file_dialog {
            d.type_folder("{source}/{n}");
        }
        h.run_steps(2);
        assert!(h.query_by_label_contains("n'a pas de sens ici").is_some());
        // Un gabarit avec des champs : résolu pour l'image.
        let template = format!("{}/{{folder}}", dir.path().join("par").display());
        if let Some(crate::files::FileDialog::Export(d)) = &mut h.state_mut().file_dialog {
            d.type_folder(&template);
        }
        h.run_steps(1);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.file_dialog.is_none()
        });
        assert!(dir.path().join("par/photos/img0.jpg").is_file());
    }

    #[test]
    fn an_export_asked_during_another_waits_its_turn() {
        // #400 : un export demandé pendant un autre attend dans la file, puis part ; un
        // export retiré de la file ne part pas.
        let (mut h, dir) = harness();
        h.run_steps(3);
        let ctx = h.ctx.clone();
        let profile = tri::export::Profile::defaults()
            .into_iter()
            .find(|p| p.id == "asis")
            .unwrap();
        let image = dir.path().join("photos/img0.jpg");
        let out = |n: usize| dir.path().join(format!("out{n}"));
        for n in 1..=3 {
            h.state_mut().start_export(
                &ctx,
                vec![image.clone()],
                profile.clone(),
                out(n).to_string_lossy().into_owned(),
                crate::export::Render::LibRaw,
                None,
            );
        }
        assert!(h.state().export_job.is_some(), "le premier part");
        assert_eq!(h.state().export_queue.len(), 2, "les deux autres attendent");
        assert!(
            h.state()
                .notice
                .as_ref()
                .unwrap()
                .0
                .contains("2 en attente")
        );
        // Le dernier est retiré de la file (le « × » de sa ligne dans la barre d'état
        // fait exactement ceci), avant que les autres, instantanés ici, ne finissent.
        let last = h.state().export_queue.back().unwrap().id;
        h.state_mut().export_queue.retain(|q| q.id != last);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.export_queue.is_empty()
        });
        assert!(out(1).join("img0.jpg").is_file());
        assert!(out(2).join("img0.jpg").is_file(), "parti après le premier");
        assert!(!out(3).exists(), "retiré de la file");
        assert_eq!(h.state().export_toasts.len(), 2, "une bulle par export");
    }

    #[test]
    fn ctrl_e_offers_the_export_profiles_and_remembers_the_choice() {
        let (mut h, dir) = harness();
        // La grille montre le rendu LibRaw : c'est lui qu'on exporte.
        h.state_mut().grid_render = crate::grid_render::GridRender::LibRaw;
        h.run_steps(3);
        press(&mut h, Key::E, CMD);
        assert!(matches!(
            h.state().file_dialog,
            Some(crate::files::FileDialog::Export(_))
        ));
        // Sans logiciel de développement (tests) : rendu de base par LibRaw, dit dans la boîte.
        h.get_by_label_contains("Aucun logiciel de développement");
        // Des JPEG : « JPEG tel quel » proposé d'abord (liste déroulante).
        let Some(crate::files::FileDialog::Export(dialog)) = &h.state().file_dialog else {
            panic!("boîte d'export attendue");
        };
        assert_eq!(dialog.choice(), 1);
        // ↓ ↓ (sans ouvrir la liste) : profil Web ; Entrée : export en fond, puis bilan.
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        let Some(crate::files::FileDialog::Export(dialog)) = &h.state().file_dialog else {
            panic!("boîte d'export attendue");
        };
        assert_eq!(dialog.choice(), 2, "Web");
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(h.state().file_dialog.is_none());
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.notice.is_some()
        });
        let notice = h.state().notice.clone().unwrap();
        assert!(notice.0.contains("1 image exportée"), "{notice:?}");
        assert!(dir.path().join("photos/export/img0.jpg").is_file());
        // Bulle de fin au milieu de l'écran (#381), avec « Ouvrir le dossier » (pas
        // cliqué : il ouvrirait le vrai gestionnaire de fichiers).
        let toasts = &h.state().export_toasts;
        assert_eq!(toasts.len(), 1, "une bulle de fin d'export");
        let toast = &toasts[0];
        assert_eq!(toast.text, "1 image exportée");
        // Comparé en chemin : `\` sous Windows.
        assert!(
            Path::new(&toast.dest).ends_with(Path::new("photos").join("export")),
            "{}",
            toast.dest
        );
        assert!(!toast.error);
        assert!(
            toast
                .reveal
                .as_ref()
                .is_some_and(|f| f.ends_with("export/img0.jpg"))
        );
        h.run_steps(2);
        h.get_by_label("Ouvrir le dossier");
        // Rapport d'export : gardé dans le dossier de données, bouton à côté du bilan.
        let data = h
            .state()
            .data_dir
            .clone()
            .expect("dossier de données des tests");
        assert!(data.starts_with(dir.path()), "jamais les vraies données");
        let log = tri::export_log::read(&data);
        assert_eq!(log.len(), 1);
        assert_eq!(log[0].written.len(), 1);
        assert_eq!(h.state().export_log, log);
        // Clic recommencé si le bouton a bougé (barre d'état : calculs de fond qui finissent).
        run_until(&mut h, |app| app.progress.iter().all(|p| p.done >= p.total));
        // Image où l'export a fini : barre d'état dessinée avant le bilan ; une de plus.
        wait_for_label(&mut h, "Rapport d'export");
        for _ in 0..5 {
            h.get_by_label("Rapport d'export").click();
            h.run_steps(2);
            if h.state().export_report {
                break;
            }
        }
        assert!(h.state().export_report);
        wait_for_label(&mut h, "Effacer la liste");
        h.get_by_label("Effacer la liste").click();
        h.run_steps(2);
        assert!(h.state().export_log.is_empty());
        assert!(tri::export_log::read(&data).is_empty(), "effacé du disque");
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(!h.state().export_report);
        press(&mut h, Key::E, CMD | Modifiers::SHIFT);
        assert!(h.state().export_report, "Ctrl+Maj+E");
        press(&mut h, Key::E, CMD | Modifiers::SHIFT);
        assert!(!h.state().export_report);
        // Rouverte : le profil choisi la dernière fois.
        press(&mut h, Key::E, CMD);
        let Some(crate::files::FileDialog::Export(dialog)) = &h.state().file_dialog else {
            panic!("boîte d'export attendue");
        };
        assert_eq!(dialog.choice(), 2);
        // En grille sur le rendu LibRaw : rendu LibRaw.
        assert_eq!(dialog.render(), crate::export::Render::LibRaw);
        // JPEG, rendu local : la case « sans recompression » est proposée, cochée.
        h.get_by_label("Sans recompression");
        assert!(dialog.passthrough());
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().file_dialog.is_none());
        // On exporte ce qu'on regarde : plein écran sur le JPEG boîtier, puis le rendu RAW.
        h.state_mut().grid_render = crate::grid_render::GridRender::Embedded;
        press(&mut h, Key::Enter, Modifiers::NONE);
        for (key, expected) in [
            (None, crate::export::Render::Embedded),
            (Some(Key::R), crate::export::Render::LibRaw),
        ] {
            if let Some(key) = key {
                press(&mut h, key, Modifiers::NONE);
            }
            press(&mut h, Key::E, CMD);
            let Some(crate::files::FileDialog::Export(dialog)) = &h.state().file_dialog else {
                panic!("boîte d'export attendue");
            };
            assert_eq!(dialog.render(), expected);
            // Images du test : des JPEG, « tel quel » toujours proposé (un rendu de RAW ne
            // le propose pas : `what_is_exported_is_what_is_looked_at`).
            assert!(dialog.lists_as_is());
            press(&mut h, Key::Escape, Modifiers::NONE);
        }
    }

    #[test]
    fn r_crops_a_version_saved_in_the_sidecar_and_undone() {
        let (mut h, dir) = harness();
        h.run_steps(3);
        let image = h.state().files[0].path.clone();
        // v depuis la grille : plein écran et nouvelle version (07/11/2026 : c avant).
        press(&mut h, Key::V, Modifiers::NONE);
        h.run_steps(3);
        assert_eq!(h.state().mode, Mode::View);
        assert!(h.state().crop.is_some());
        // Image affichée : le cadre connaît ses proportions (suite de tests chargée).
        run_until(&mut h, |app| {
            app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
        });
        // Rapport de l'image : « Version » (« Recadrage » avant le 07/11/2026), pas
        // « Original », réservé à l'image non recadrée dans la liste des versions (retour
        // du 23/10/2026).
        assert_eq!(
            h.state().crop.as_ref().unwrap().name,
            t!("crop-name-original-ratio")
        );
        h.state_mut().crop.as_mut().unwrap().name = "original".into();
        assert!(h.state().crop.as_ref().unwrap().name_taken());
        h.state_mut().crop.as_mut().unwrap().name = t!("crop-name-original-ratio");
        // 5 : 3:2 ; flèches : le cadre bouge, l'image reste la même.
        press(&mut h, Key::Num5, Modifiers::NONE);
        let before = h.state().crop.as_ref().unwrap().rect;
        press(&mut h, Key::ArrowDown, Modifiers::NONE);
        press(&mut h, Key::ArrowRight, Modifiers::NONE);
        assert_eq!(h.state().selected, 0, "pas d'image suivante");
        let after = h.state().crop.as_ref().unwrap().rect;
        assert!(after.y > before.y, "déplacé : {before:?} → {after:?}");
        // Entrée : enregistrée dans le sidecar, recadrage fermé.
        press(&mut h, Key::Enter, Modifiers::NONE);
        assert!(h.state().crop.is_none());
        let saved = tri::versions::read(&image).unwrap();
        assert_eq!(saved.list.len(), 1);
        assert_eq!(saved.list[0].name, "3:2");
        assert_eq!(saved.list[0].ratio, tri::versions::Ratio::Fixed(3, 2));
        assert!(dir.path().join("photos/img0.jpg.xmp").is_file());
        // Montrée tout de suite, dans la liste des versions du bandeau (issue n° 5).
        assert_eq!(h.state().version_shown, Some((image.clone(), 0)));
        h.run_steps(2);
        // La liste des versions, dans le bandeau du bas (le panneau de droite a aussi celle
        // du tri, et celle de la balance des réglages) : celle qui montre une version.
        let versions_list = |h: &Harness<'_, TriApp>| {
            h.query_all_by_role(egui::accesskit::Role::ComboBox)
                .filter(|n| n.value().is_some_and(|v| v.starts_with("Versions")))
                .max_by(|a, b| a.rect().min.y.total_cmp(&b.rect().min.y))
                .expect("liste des versions")
                .click();
        };
        versions_list(&h);
        h.run_steps(2);
        h.get_by_label("Original").click();
        h.run_steps(2);
        assert_eq!(h.state().version_shown, None);
        versions_list(&h);
        h.run_steps(2);
        h.get_by_label("3:2").click();
        h.run_steps(2);
        assert_eq!(
            h.state().version_shown,
            Some((image.clone(), 0)),
            "remontrée"
        );
        // Ctrl+E sur la version montrée : elle seule, recadrée, nommée d'après elle.
        press(&mut h, Key::E, CMD);
        press(&mut h, Key::Enter, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.export_job.is_none() && app.notice.is_some()
        });
        let out = dir.path().join("photos/export/img0-3_2.jpg");
        assert!(out.is_file(), "{:?}", h.state().notice);
        let (w, h2) = image::image_dimensions(&out).unwrap();
        assert!(
            (f64::from(w) / f64::from(h2) - 1.5).abs() < 0.05,
            "3:2 : {w} × {h2}"
        );
        // Maj+V : version suivante (ici la seule), puis l'original ; Ctrl+Maj+V dans
        // l'autre sens (07/11/2026 : v crée une version).
        let shift = Modifiers::SHIFT;
        let back = CMD | Modifiers::SHIFT;
        press(&mut h, Key::V, shift);
        assert_eq!(h.state().version_shown, None);
        press(&mut h, Key::V, shift);
        assert_eq!(h.state().version_shown, Some((image.clone(), 0)));
        press(&mut h, Key::V, back);
        assert_eq!(h.state().version_shown, None, "Ctrl+Maj+V : l'original");
        press(&mut h, Key::V, back);
        assert_eq!(
            h.state().version_shown,
            Some((image.clone(), 0)),
            "Ctrl+Maj+V : la dernière version"
        );
        // Supprimer (dans la liste, annulable), puis Ctrl+Z la remet.
        versions_list(&h);
        h.run_steps(2);
        h.get_by_label("Supprimer").click();
        h.run_steps(2);
        // Confirmation (retour du 16/11/2026), puis supprimée.
        assert!(h.state().version_delete.is_some());
        assert_eq!(tri::versions::read(&image).unwrap().list.len(), 1);
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(2);
        assert!(tri::versions::read(&image).unwrap().list.is_empty());
        press(&mut h, Key::Z, CMD);
        assert_eq!(tri::versions::read(&image).unwrap().list.len(), 1);
        // Et Ctrl+Z encore : la création défaite.
        press(&mut h, Key::Z, CMD);
        assert!(tri::versions::read(&image).unwrap().list.is_empty());
        // Échap abandonne sans rien écrire.
        press(&mut h, Key::V, Modifiers::NONE);
        press(&mut h, Key::Escape, Modifiers::NONE);
        assert!(h.state().crop.is_none());
        assert_eq!(
            h.state().mode,
            Mode::View,
            "Échap ferme le recadrage seulement"
        );
        assert!(tri::versions::read(&image).unwrap().list.is_empty());
    }

    #[test]
    fn a_custom_ratio_is_typed_in_the_ratio_list() {
        // Idée de l'utilisateur (07/11/2026) : un rapport à soi, « 17:23 ».
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::V, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
        });
        // La liste du rapport s'ouvre (elle montre le rapport en cours).
        let current = crate::crop::ratio_name(h.state().crop.as_ref().unwrap().ratio);
        let list = h
            .get_all_by_role(egui::accesskit::Role::ComboBox)
            .find(|n| n.value().as_deref() == Some(current.as_str()))
            .expect("la liste du rapport");
        list.click();
        h.run_steps(3);
        // La liste ouverte garde sa largeur (07/11/2026 : elle s'élargissait à chaque
        // image).
        let width = |h: &Harness<'_, TriApp>| {
            h.get_all_by_role(egui::accesskit::Role::TextInput)
                .map(|n| n.rect().width())
                .fold(0.0, f32::max)
        };
        let before = width(&h);
        h.run_steps(20);
        assert_eq!(width(&h), before, "largeur stable");
        // Le champ du rapport : vide (celui du nom porte le nom).
        let name = h.state().crop.as_ref().unwrap().name.clone();
        h.get_all_by_role(egui::accesskit::Role::TextInput)
            .find(|n| n.value().as_deref() != Some(name.as_str()))
            .expect("le champ du rapport")
            .click();
        h.run_steps(2);
        type_text(&mut h, "17:23");
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(2);
        let crop = h
            .state()
            .crop
            .as_ref()
            .expect("toujours en cours, Entrée ne l'a pas fermé");
        assert_eq!(crop.ratio, tri::versions::Ratio::Fixed(17, 23));
        assert_eq!(crop.name, "17:23", "le nom suit le rapport");
        // « + » : le rapport rejoint la liste, gardé dans la configuration.
        let current = crate::crop::ratio_name(h.state().crop.as_ref().unwrap().ratio);
        h.get_all_by_role(egui::accesskit::Role::ComboBox)
            .find(|n| n.value().as_deref() == Some(current.as_str()))
            .expect("la liste du rapport")
            .click();
        h.run_steps(3);
        let name = h.state().crop.as_ref().unwrap().name.clone();
        h.get_all_by_role(egui::accesskit::Role::TextInput)
            .find(|n| n.value().as_deref() != Some(name.as_str()))
            .expect("le champ du rapport")
            .click();
        h.run_steps(2);
        type_text(&mut h, "1.91:1");
        h.run_steps(2);
        h.get_by_label("+").click();
        h.run_steps(3);
        let wide = tri::versions::Ratio::Fixed(191, 100);
        assert_eq!(h.state().crop.as_ref().unwrap().ratio, wide);
        assert_eq!(h.state().settings.versions.ratios, [wide]);
        let config = h.state().config_path.clone().unwrap();
        let written = std::fs::read_to_string(config).unwrap();
        assert!(written.contains("191:100"), "{written}");
        // Sans nom, la disquette est grisée.
        h.state_mut().crop.as_mut().unwrap().name.clear();
        h.run_steps(2);
        assert!(
            format!("{:?}", h.get_by_label(&t!("crop-preset-save"))).contains("disabled: true"),
            "disquette grisée"
        );
    }

    #[test]
    fn every_part_of_the_version_bar_has_its_keys() {
        // Demandé le 07/11/2026 : chaque partie de la barre au clavier. v / Maj+V le
        // préréglage de version, r / Maj+R le rapport, x l'orientation, o les guides, / un
        // rapport à soi, e / Maj+E l'export, n (ou F2) le nom, Ctrl+S la disquette.
        use tri::versions::Ratio;
        let (mut h, _dir) = harness();
        h.run_steps(3);
        press(&mut h, Key::V, Modifiers::NONE);
        run_until(&mut h, |app| {
            app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
        });
        let ratio = |h: &Harness<'_, TriApp>| h.state().crop.as_ref().unwrap().ratio;
        let start = ratio(&h);
        press(&mut h, Key::R, Modifiers::NONE);
        assert_ne!(ratio(&h), start, "r : le rapport suivant");
        press(&mut h, Key::R, Modifiers::SHIFT);
        assert!(ratio(&h).same_shape(start), "Maj+R : de retour");
        let profile = |h: &Harness<'_, TriApp>| h.state().crop.as_ref().unwrap().profile.clone();
        assert_eq!(profile(&h), None);
        press(&mut h, Key::E, Modifiers::NONE);
        assert!(profile(&h).is_some(), "e : un préréglage d'export");
        press(&mut h, Key::E, Modifiers::SHIFT);
        assert_eq!(profile(&h), None, "Maj+E : aucun");
        // / : la liste s'ouvre sur le champ, qui prend le clavier.
        type_text(&mut h, "/");
        h.run_steps(3);
        assert!(
            h.ctx.egui_wants_keyboard_input(),
            "le champ du rapport a le clavier"
        );
        type_text(&mut h, "17:23");
        press(&mut h, Key::Enter, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(ratio(&h), Ratio::Fixed(17, 23));
        assert!(
            h.state().crop.is_some(),
            "Entrée n'a pas enregistré la version"
        );
        // 0 : le cadre d'origine, l'image entière (aussi Ctrl+clic sur « Original »).
        press(&mut h, Key::Num0, Modifiers::NONE);
        assert_eq!(ratio(&h), Ratio::Original { flipped: false });
        assert_eq!(
            h.state().crop.as_ref().unwrap().rect,
            tri::versions::Rect::FULL
        );
        // x : l'orientation ; o : les superpositions, qui se calent sur le cadre.
        press(&mut h, Key::X, Modifiers::NONE);
        assert_eq!(ratio(&h), Ratio::Original { flipped: true }, "x : tournée");
        press(&mut h, Key::X, Modifiers::NONE);
        assert_eq!(ratio(&h), Ratio::Original { flipped: false });
        let overlay = h.state().overlay;
        press(&mut h, Key::O, Modifiers::NONE);
        assert_ne!(h.state().overlay, overlay, "o : une superposition");
        assert_eq!(
            ratio(&h),
            Ratio::Original { flipped: false },
            "o ne tourne pas"
        );
        // n : le nom (F2 aussi) ; Ctrl+S : un préréglage (dans la configuration du test).
        press(&mut h, Key::N, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.ctx.egui_wants_keyboard_input(), "le nom a le clavier");
        // Ctrl+Échap (comme sur les listes) : le champ rend le clavier, la version reste
        // ouverte (retour du 07/11/2026).
        press(&mut h, Key::Escape, Modifiers::CTRL);
        h.run_steps(2);
        assert!(
            !h.ctx.egui_wants_keyboard_input(),
            "Ctrl+Échap : sorti du nom"
        );
        assert!(h.state().crop.is_some(), "Ctrl+Échap : version gardée");
        press(&mut h, Key::N, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.ctx.egui_wants_keyboard_input());
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.ctx.memory_mut(|m| m.stop_text_input());
        h.run_steps(2);
        let before = h.state().settings.versions.presets.0.len();
        if h.state().crop.is_none() {
            press(&mut h, Key::V, Modifiers::NONE);
            run_until(&mut h, |app| {
                app.crop.as_ref().is_some_and(crate::crop::Crop::ready)
            });
        }
        press(&mut h, Key::S, CMD);
        assert_eq!(h.state().settings.versions.presets.0.len(), before + 1);
        // v / Maj+V : de préréglage en préréglage, sans quitter la version en cours.
        let preset = |h: &Harness<'_, TriApp>| h.state().crop.as_ref().unwrap().preset.clone();
        press(&mut h, Key::V, Modifiers::NONE);
        let first = preset(&h);
        assert!(first.is_some(), "v : un préréglage de version");
        press(&mut h, Key::V, Modifiers::NONE);
        assert_ne!(preset(&h), first, "v : le suivant");
        press(&mut h, Key::V, Modifiers::SHIFT);
        assert_eq!(preset(&h), first, "Maj+V : le précédent");
    }

    #[test]
    fn ratings_are_written_into_the_images_and_read_back_on_demand() {
        // Issue n° 276 : sur demande, les notes vont dans les images elles-mêmes, et en
        // reviennent.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let image = h.state().files[0].path.clone();
        press(&mut h, Key::Num4, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(h.state().folder.notes.notes(&image).stars, 4);
        assert_eq!(
            tri::embedded::read(&image).unwrap(),
            None,
            "pas dans l'image sans le demander"
        );
        act(&mut h, Action::EmbedNotes);
        run_until(&mut h, |app| app.embed_job.is_none());
        let inside = tri::embedded::read(&image).unwrap().expect("inscrites");
        assert_eq!(inside.stars, 4);
        assert_eq!(
            h.state().notice.as_ref().map(|n| n.1),
            Some(false),
            "pas d'erreur"
        );
        // Changées dans un autre logiciel (XnView…) : relues sur demande, annulables.
        let mut two = tri::xmp::Notes::default();
        two.set_stars(2);
        tri::embedded::write(&image, &two).unwrap();
        act(&mut h, Action::ImportNotes);
        h.run_steps(2);
        assert_eq!(h.state().folder.notes.notes(&image).stars, 2, "relues");
        assert_eq!(tri::xmp::read(&image).unwrap().stars, 2, "dans le sidecar");
        act(&mut h, Action::Undo);
        h.run_steps(2);
        assert_eq!(h.state().folder.notes.notes(&image).stars, 4, "annulé");
    }

    #[test]
    fn ratings_are_synced_by_themselves_where_the_setting_says() {
        // Issue n° 368, automatisation : `[xmp] embed`, le réglage du dossier, et la
        // propagation d'une fusion venue d'un autre logiciel.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let image = h.state().files[0].path.clone();
        let folder = h.state().folder.dir.clone();
        let inside = |p: &Path| tri::embedded::read(p).unwrap().map(|n| n.stars);
        // Par défaut : rien dans l'image.
        press(&mut h, Key::Num2, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(inside(&image), None);
        // Partout : la note va aussi dans l'image.
        h.state_mut().settings.xmp.embed = tri::embedded::Auto::Everywhere;
        h.state_mut().apply_sidecar_policy();
        press(&mut h, Key::Num3, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(inside(&image), Some(3));
        assert!(h.state().note_error.is_none());
        // Ce dossier-là, jamais (le réglage du dossier l'emporte).
        h.state_mut()
            .folder
            .notes
            .set_folder_embed(&folder, Some(false))
            .unwrap();
        press(&mut h, Key::Num4, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(inside(&image), Some(3), "plus d'écriture dans ce dossier");
        h.state_mut()
            .folder
            .notes
            .set_folder_embed(&folder, None)
            .unwrap();
        // Une couleur posée ailleurs dans l'image : fusionnée, et propagée au sidecar.
        let mut red = tri::xmp::Notes::default();
        red.set_stars(4);
        red.colors = vec![tri::xmp::Color::Red];
        tri::embedded::write(&image, &red).unwrap();
        h.state_mut().folder.notes.reload();
        h.run_steps(3);
        assert_eq!(
            h.state().folder.notes.notes(&image).colors,
            [tri::xmp::Color::Red]
        );
        assert_eq!(
            tri::xmp::read(&image).unwrap().colors,
            [tri::xmp::Color::Red],
            "propagée au sidecar"
        );
        assert!(h.state().folder.notes.conflicts().is_empty());
    }

    #[test]
    fn ratings_in_conflict_are_settled_in_a_dialog() {
        // Issue n° 368 : le sidecar dit 2 étoiles, l'image 4, jamais vus ensemble.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        let image = h.state().files[0].path.clone();
        let mut four = tri::xmp::Notes::default();
        four.set_stars(4);
        four.colors = vec![tri::xmp::Color::Green];
        tri::embedded::write(&image, &four).unwrap();
        let mut two = tri::xmp::Notes::default();
        two.set_stars(2);
        tri::xmp::write(&image, &two, tri::xmp::Convention::Darktable).unwrap();
        h.state_mut().folder.notes.reload();
        h.run_steps(2);
        assert!(h.state().folder.notes.conflict(&image).is_some());
        // Relire depuis les images : pas tranché en silence (retour du 07/11/2026), la
        // boîte s'ouvre.
        // Filtre « en conflit », dans le panneau de droite : elle seule.
        // La case est là ; elle déclenche l'action, éprouvée ici directement (un clic
        // simulé n'est pas toujours vu sur la CI Windows, voir les tests du 31/10/2026).
        h.state_mut().metadata_panel = true;
        h.run_steps(2);
        assert!(
            h.query_by_label(&t!("filter-conflicts")).is_some(),
            "dans le panneau"
        );
        act(&mut h, Action::FilterConflicts);
        h.run_steps(2);
        assert!(h.state().conflicts_only);
        assert_eq!(h.state().files.len(), 1, "l'image en conflit seule");
        act(&mut h, Action::FilterConflicts);
        h.run_steps(2);
        assert_eq!(h.state().files.len(), 3);
        // Au clavier : f c.
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::C, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().conflicts_only, "f c");
        press(&mut h, Key::F, Modifiers::NONE);
        press(&mut h, Key::C, Modifiers::NONE);
        h.run_steps(2);
        assert!(!h.state().conflicts_only);
        let inside = std::fs::read(&image).unwrap();
        for action in [Action::ImportNotes, Action::EmbedNotes] {
            act(&mut h, action);
            run_until(&mut h, |app| app.embed_job.is_none());
            assert!(
                h.state().conflict_dialog.is_some(),
                "{action:?} : boîte ouverte"
            );
            assert!(
                h.state().folder.notes.conflict(&image).is_some(),
                "pas tranché"
            );
            assert_eq!(tri::xmp::read(&image).unwrap().stars, 2, "sidecar intact");
            assert_eq!(std::fs::read(&image).unwrap(), inside, "image intacte");
            h.state_mut().conflict_dialog = None;
        }
        // Noter : la boîte s'ouvre, rien n'est écrit.
        press(&mut h, Key::Num5, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().conflict_dialog.is_some(), "boîte ouverte");
        assert_eq!(tri::xmp::read(&image).unwrap().stars, 2, "rien écrit");
        assert_eq!(
            h.query_all_by_label(&t!("conflict-keep")).count(),
            2,
            "un « Garder » par source"
        );
        // La date de modification de chaque source (08/11/2026), à l'heure locale :
        // celle du sidecar, telle que la montre la boîte (cellules dessinées, pas de
        // libellé accessible : vérifié par capture).
        let conflict = h.state().folder.notes.conflict(&image).cloned().unwrap();
        let sidecar = tri::xmp::sidecar_path(&image, Default::default());
        let stamp = tri::reconcile::Stamp::of(&sidecar).unwrap().modified;
        assert!(
            conflict.modified.contains(&stamp),
            "{:?}",
            conflict.modified
        );
        assert!(
            modified_text(stamp).contains(':'),
            "{}",
            modified_text(stamp)
        );
        // Champ par champ (retour du 07/11/2026) : les étoiles du sidecar (choisies
        // d'office : les plus récentes), la couleur de l'image.
        let green = t!("color-green");
        h.query_all_by_label(&green).next().unwrap().click();
        h.run_steps(2);
        h.get_by_label(&t!("conflict-apply")).click();
        h.run_steps(2);
        assert!(h.state().conflict_dialog.is_none());
        assert!(h.state().folder.notes.conflict(&image).is_none(), "tranché");
        let kept = h.state().folder.notes.notes(&image).clone();
        assert_eq!(
            (kept.stars, kept.colors.clone()),
            (2, vec![tri::xmp::Color::Green])
        );
        assert_eq!(
            tri::xmp::read(&image).unwrap(),
            kept,
            "écrit dans le sidecar"
        );
        // Puis on note normalement ; et l'annulation revient en arrière.
        press(&mut h, Key::Num5, Modifiers::NONE);
        h.run_steps(2);
        assert_eq!(h.state().folder.notes.notes(&image).stars, 5);
        act(&mut h, Action::Undo);
        act(&mut h, Action::Undo);
        h.run_steps(2);
        assert_eq!(
            tri::xmp::read(&image).unwrap().stars,
            2,
            "annulé jusqu'au départ"
        );
    }

    #[test]
    fn leaving_a_version_goes_back_where_it_was_started() {
        // Retour du 07/11/2026 : commencée depuis la grille, Échap y ramène ; depuis le
        // plein écran, on y reste.
        let (mut h, _dir) = harness();
        h.run_steps(3);
        assert_eq!(h.state().mode, Mode::Grid);
        press(&mut h, Key::V, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().crop.is_some());
        assert_eq!(h.state().mode, Mode::View);
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().crop.is_none());
        assert_eq!(h.state().mode, Mode::Grid, "de retour dans la grille");
        act(&mut h, Action::Open);
        h.run_steps(2);
        press(&mut h, Key::V, Modifiers::NONE);
        h.run_steps(2);
        press(&mut h, Key::Escape, Modifiers::NONE);
        h.run_steps(2);
        assert!(h.state().crop.is_none());
        assert_eq!(h.state().mode, Mode::View, "le plein écran reste");
    }

