    #[test]
    fn the_help_lists_the_template_fields_and_finds_them() {
        // Une seule aide pour les champs du renommage par lot et des dossiers d'export,
        // tirée du moteur, cherchée comme le reste (« gabarit », un champ).
        let keymap = Keymap::default();
        let fields = |query: &str| -> Vec<String> {
            HelpLines::new(&keymap, query, &[])
                .lines
                .iter()
                .filter_map(|l| match l {
                    HelpLine::Field(f) => Some(f.token.clone()),
                    _ => None,
                })
                .collect()
        };
        let all = fields("");
        assert_eq!(all.len(), tri::naming::FIELDS.len() + 1, "{all:?}");
        assert!(all.contains(&"{source}".to_string()));
        assert_eq!(fields("gabarit").len(), all.len(), "le mot du groupe");
        assert!(fields("camera").contains(&"{camera}".to_string()));
        assert!(fields("compteur").contains(&"{n}".to_string()));
    }

    #[test]
    fn help_rows_are_grouped_then_ranked_by_search() {
        let keymap = Keymap::default();
        let all = help_rows(&keymap, "");
        // Toutes les actions disponibles sur ce système (AirDrop : macOS seulement).
        let available = Action::ALL.iter().filter(|a| a.available()).count();
        assert_eq!(all.len(), available);
        let ranks: Vec<usize> = all
            .iter()
            .map(|(a, _)| Group::ALL.iter().position(|g| *g == a.group()).unwrap())
            .collect();
        assert!(ranks.is_sorted(), "rangées par thème");
        // Recherche par raccourci et par identifiant aussi.
        let by_id = help_rows(&keymap, "core.nav.next");
        assert_eq!(by_id[0].0, Action::NavNext);
        let stars = help_rows(&keymap, "etoile 3");
        assert_eq!(stars[0].0, Action::Stars(3));
        // Rangées par thème pendant la recherche aussi : chaque thème d'un seul tenant.
        let found = help_rows(&keymap, "zoom");
        let mut seen: Vec<Group> = Vec::new();
        for (a, _) in &found {
            if seen.last() != Some(&a.group()) {
                assert!(!seen.contains(&a.group()), "{:?} coupé en deux", a.group());
                seen.push(a.group());
            }
        }
        // Mots-clés cachés : « vim » trouve le mode visuel, et seulement des actions qui
        // le contiennent tel quel (plus de lettres éparpillées).
        crate::i18n::ensure();
        let vim = help_rows(&keymap, "vim");
        assert!(
            vim.iter().any(|(a, _)| *a == Action::SelectVisual),
            "{vim:?}"
        );
        assert!(vim.len() < 10, "{vim:?}");
        // Le titre d'un thème trouve tout le thème.
        let group = Action::Stars(3).group();
        let by_group = help_rows(&keymap, &group.label());
        let count = Action::ALL
            .iter()
            .filter(|a| a.available() && a.group() == group)
            .count();
        assert!(by_group.iter().filter(|(a, _)| a.group() == group).count() == count);
    }

    #[test]
    fn analysis_filters_follow_the_computation() {
        // Issue n° 73 : filtre allumé pendant les analyses, la barre d'état le dit, et la
        // grille se refiltre au fil du calcul (au plus toutes les `analysis_refilter_ms`).
        let (mut h, _dir) = harness();
        let app = h.state_mut();
        let half = Progress { done: 1, total: 3 };
        app.gui.analysis_refilter_ms = 0;
        app.refiltered_at = Instant::now() - Duration::from_secs(3600);
        assert!(!app.analysis_refilter_due(half), "0 : à la fin seulement");
        assert!(app.analysis_refilter_due(Progress { done: 3, total: 3 }));
        app.gui.analysis_refilter_ms = 1000;
        assert!(app.analysis_refilter_due(half), "dernier refiltrage ancien");
        app.refilter(Reveal::Minimal);
        assert!(!app.analysis_refilter_due(half), "refiltré à l'instant");
        app.notice = None;
        app.analysis_partial_notice(half);
        let notice = app.notice.clone().map(|(text, _)| text).unwrap_or_default();
        assert!(notice.contains("1 / 3"), "{notice}");
        app.notice = None;
        app.analysis_partial_notice(Progress { done: 3, total: 3 });
        assert!(app.notice.is_none(), "tout analysé : rien à dire");
    }

    #[test]
    fn removed_analyses_take_their_tools_away() {
        // #564 : palettes, piles et netteté retirées dans les réglages : ni filtre, ni
        // interrupteur, ni calcul proposé, ni aide ; l'exposition reste.
        use tri::scheduler::Analysis;
        let images = (0..2)
            .map(|i| {
                let name = ["a.jpg", "b.jpg"][i];
                (
                    name,
                    image::RgbImage::from_pixel(32, 24, image::Rgb([200, 40, 40])),
                )
            })
            .collect();
        let (mut h, _dir) = harness_tuned(images, |s, _| {
            s.analysis.palettes = Analysis::Off;
            s.analysis.stacks = Analysis::Off;
            s.analysis.sharpness = Analysis::Off;
        });
        h.run_steps(3);
        let app = h.state();
        assert!(app.palette_toggles().is_empty());
        let toggles: Vec<Action> = app.content_toggles().iter().map(|t| t.0).collect();
        assert!(!toggles.contains(&Action::FilterBlurry), "{toggles:?}");
        assert!(toggles.contains(&Action::FilterWellExposed), "{toggles:?}");
        for action in [
            Action::FilterPalette,
            Action::FilterPaletteColour,
            Action::StackMode,
            Action::GroupingWindow,
            Action::FilterBlurry,
            Action::FolderCompute(tri::compute::Kind::Signatures),
            Action::Compute(tri::compute::Kind::Palette(tri::palette::SourceKind::Raw)),
        ] {
            assert!(!action.available(), "{action:?}");
            assert!(app.action_unusable(action).is_some(), "{action:?}");
        }
        assert!(Action::FilterWellExposed.available());
        assert!(Action::FolderCompute(tri::compute::Kind::Exposure).available());
        assert!(app.compute_palette_kinds().is_empty());
        assert!(!app.stacking);
        // Ni dans le panneau (section Palette, interrupteur des piles).
        assert!(h.query_by_label(&t!("panel-section-palette")).is_none());
        assert!(h.query_by_label(&t!("panel-grid-stacks-on")).is_none());
        // Ni dans l'aide.
        let help = help_rows(&h.state().keymap, "");
        assert!(help.iter().all(|(a, _)| a.available()));
        assert!(!help.iter().any(|(a, _)| *a == Action::StackMode));
        // Remises dans les réglages : de retour tout de suite.
        let mut settings = AppSettings::default();
        settings.analysis = h.state().settings.analysis;
        settings.analysis.palettes = Analysis::Background;
        let ctx = h.ctx.clone();
        h.state_mut().apply_settings(&ctx, settings);
        h.run_steps(3);
        assert!(Action::FilterPalette.available());
        assert_eq!(h.state().palette_toggles().len(), 2);
        assert!(!Action::StackMode.available(), "les piles restent retirées");
    }

    #[test]
    fn a_removed_analysis_leaves_the_help_and_the_settings_too() {
        // Retours du 22/11/2026 : exposition retirée, tout part (histogrammes, zones) ;
        // dans l'aide, `?` et `:`, ses actions et ses réglages aussi ; une page de réglages
        // qui n'est qu'à elle garde son titre et le dit ; une ligne parmi d'autres sans
        // rapport part seule. Les touches de pile servent aussi aux développements :
        // elles restent sans les piles automatiques.
        use tri::scheduler::Analysis;
        let images = vec![(
            "a.jpg",
            image::RgbImage::from_pixel(32, 24, image::Rgb([200, 40, 40])),
        )];
        let (mut h, dir) = harness_tuned(images, |s, _| {
            s.analysis.exposure = Analysis::Off;
            s.analysis.stacks = Analysis::Off;
            s.analysis.palettes = Analysis::Off;
        });
        h.state_mut().metadata_panel = true;
        h.run_steps(3);
        for action in [
            Action::ToggleHistogram,
            Action::HistogramLarge,
            Action::ToggleClipping,
            Action::FilterWellExposed,
            Action::StackMode,
        ] {
            assert!(!action.available(), "{action:?}");
        }
        for action in [Action::StackOpen, Action::StackClose, Action::StackChoose] {
            assert!(action.available(), "développements : {action:?}");
        }
        assert!(h.query_by_label(&t!("panel-section-histogram")).is_none());
        h.state_mut().histogram_large = true;
        h.run_steps(2);
        assert!(h.query_by_label(&Action::HistogramScale.label()).is_none());
        // Réglages de `:` : ni les sections des analyses retirées, ni leurs lignes isolées ;
        // le reste, si.
        let listed = crate::settings_window::settings_list(&[]);
        let has =
            |section: &str, key: &str| listed.iter().any(|r| r.section == section && r.key == key);
        assert!(!listed.iter().any(|r| r.section == "exposure"
            || r.section == "colours"
            || r.section == "gui.colours_view"));
        assert!(!has("gui.histogram", "scale"));
        assert!(!has("gui.metadata", "histogram"));
        assert!(!has("gui.grid", "stacks"));
        assert!(has("gui.metadata", "group_gap"), "ligne sans rapport");
        assert!(has("sharpness", "threshold"), "carte de netteté");
        assert!(has("gui.dialogs", "palette_max"), "palette de commandes");
        // Page à elle : titre et mention, pas ses réglages.
        h.state_mut().config_path = Some(dir.path().join("config.toml"));
        press(&mut h, Key::Comma, CMD);
        h.state_mut()
            .settings_window
            .as_mut()
            .unwrap()
            .show_section("colours");
        h.run_steps(3);
        assert!(h.query_by_label(&t!("settings-analysis-removed")).is_some());
        h.get_by_label(&t!("settings-section-analysis")).click();
        h.run_steps(3);
        assert_eq!(
            h.state().settings_window.as_ref().unwrap().section_name(),
            "analysis"
        );
    }

    #[test]
    fn an_on_demand_analysis_waits_for_the_folder_to_be_computed() {
        // #564 : netteté « à la demande » : rien en fond, le filtre « floues » grisé tant
        // que le dossier n'est pas dans le cache ; « Calculer » sur le dossier le dégrise.
        use tri::scheduler::Analysis;
        let images = (0..3)
            .map(|i| {
                let name = ["a.jpg", "b.jpg", "c.jpg"][i];
                let pixel = image::Rgb([(60 * i) as u8, 100, 160]);
                (name, image::RgbImage::from_pixel(32, 24, pixel))
            })
            .collect();
        let (mut h, dir) = harness_tuned(images, |s, _| {
            s.analysis.sharpness = Analysis::OnDemand;
        });
        run_until(&mut h, |app| app.analysis_missing[4] == 3);
        let why = h.state().action_unusable(Action::FilterBlurry);
        assert_eq!(why, Some(t!("filter-analysis-on-demand", missing = 3)));
        assert!(Action::FilterBlurry.available(), "grisé, pas retiré");
        let ctx = h.ctx.clone();
        let photos = dir.path().join("photos");
        h.state_mut().compute_action(
            &ctx,
            Action::FolderCompute(tri::compute::Kind::Sharpness),
            crate::compute_tasks::Target::Folder(photos),
        );
        run_until(&mut h, |app| {
            app.compute_tasks.is_empty() && app.action_unusable(Action::FilterBlurry).is_none()
        });
        assert_eq!(h.state().analysis_missing[4], 0);
    }
